window.BANK['so7']['so7-1-1'] = [
  {"q":"الكون هو:","o":["الشمس والقمر فقط","كل ما يحيط بنا من نجوم ومجرات ومخلوقات حية","كوكب الأرض فقط"],"a":1,"why":"الكون هو كل ما يحيط بنا من نجوم ومجرات ومخلوقات حية، فهو المكان الذي يضم مخلوقات الله كلها. فلا يقتصر على الأرض أو الشمس.","ow":["الشمس والقمر جزء صغير من الكون وليسا كله.","","الأرض كوكب واحد داخل الكون الواسع."]},
  {"q":"المجرة هي:","o":["كوكب كبير","جسم صغير يدور حول الشمس","مجموعة هائلة الحجم من النجوم والكواكب والأقمار والمذنبات"],"a":2,"why":"المجرة مجموعة هائلة الحجم من النجوم والكواكب والأقمار والمذنبات. وأشهر مثال عليها مجرة درب التبانة التي تنتمي إليها مجموعتنا الشمسية.","ow":["الكوكب الكبير جسم واحد وليس مجموعة هائلة.","الجسم الصغير الذي يدور حول الشمس يسمى كويكبًا أو مذنبًا.",""]},
  {"q":"يتكون الكون من عدد هائل من:","o":["المجرات","الشموس فقط","الأقمار فقط"],"a":0,"why":"يتكون الكون من عدد هائل من المجرات، وفي كل مجرة نجوم وكواكب كثيرة. فلا يقتصر على الشموس أو الأقمار.","ow":["","الشموس جزء من المجرات وليست كل ما في الكون.","الأقمار جزء صغير من الكون."]},
  {"q":"النجم الوحيد في المجموعة الشمسية هو:","o":["الأرض","القمر","عطارد","الشمس"],"a":3,"why":"النجم الوحيد في المجموعة الشمسية هو الشمس، وهي ملتهبة تشع الحرارة والضوء، أما الأرض وعطارد فكواكب والقمر تابع.","ow":["الأرض كوكب وليست نجمًا.","القمر تابع للأرض وليس نجمًا.","عطارد كوكب وأقرب الكواكب للشمس.",""]},
  {"q":"تعد الشمس أكبر ... في نظامنا الشمسي:","o":["كائن","كوكب بارد","مذنب"],"a":0,"why":"تعد الشمس أكبر جرم في نظامنا الشمسي، وهي نجم ملتهب يتجمع حوله الكواكب، وليست كوكبًا بل نجمًا يشع الضوء.","ow":["","الشمس ليست كوكبًا باردًا، فهي ملتهبة.","المذنب جسم صغير بنواة صلبة وليس أكبر ما في النظام."]},
  {"q":"التوابع (الأقمار) هي أجرام تدور حول:","o":["بعض الكواكب","المجرات","الشمس فقط"],"a":0,"why":"التوابع أو الأقمار أجرام تدور حول بعض الكواكب في أفلاك خاصة بها. فالقمر يدور حول الأرض وليس حول الشمس مباشرة.","ow":["","المجرات أكبر بكثير ولا تدور الأقمار حولها.","الأقمار تدور حول الكواكب لا الشمس وحدها."]},
  {"q":"معظم الكويكبات تقع بين مداري:","o":["زحل ونبتون","عطارد والزهرة","المشتري والمريخ"],"a":2,"why":"معظم الكويكبات كتل صخرية أو معدنية صغيرة تقع بين مداري المشتري والمريخ، فتُسمى حزام الكويكبات. أما عطارد والزهرة فكوكبان داخليان.","ow":["زحل ونبتون كوكبان بعيدان جدًا عن موقعها.","عطارد والزهرة كوكبان قريبان من الشمس.",""]},
  {"q":"تدور المذنبات حول الشمس في مدارات:","o":["مربعة","مستقيمة","بيضوية"],"a":2,"why":"تدور المذنبات حول الشمس في مدارات بيضوية، أي كالدائرة المطولة، فتقترب من الشمس ثم تبتعد. فمدارها ليس مستقيمًا ولا مربعًا.","ow":["المدارات المربعة غير موجودة في الفلك.","المدار المستقيم لا يعود إلى الشمس.",""]},
  {"q":"تشتعل الشهب عند دخولها الغلاف الجوي بسبب:","o":["الاحتكاك بالهواء","الأمطار","الجاذبية فقط"],"a":0,"why":"تشتعل الشهب عند دخولها الغلاف الجوي بسبب الاحتكاك بالهواء، فترتفع حرارتها فتشتعل وتظهر كخط مضيء في السماء.","ow":["","الأمطار لا تشعل الشهب.","الجاذبية وحدها لا تشعلها، بل الاحتكاك."]},
  {"q":"أجسام متوسطة تخترق الغلاف الجوي ويصل جزء منها إلى الأرض:","o":["الشهب","المذنبات","النيازك","الكويكبات"],"a":2,"why":"النيازك أجسام متوسطة الحجم تخترق الغلاف الجوي ويبقى جزء منها فيصل إلى سطح الأرض. أما الشهب فتحترق كاملة غالبًا.","ow":["الشهب أجسام صغيرة تشتعل في الغلاف الجوي.","المذنبات لها ذيل مضيء ولا تصل إلى الأرض.","","الكويكبات كتل صخرية معظمها بين المشتري والمريخ."]},
  {"q":"أكبر كواكب المجموعة الشمسية حجمًا:","o":["المريخ","المشتري","الأرض","عطارد"],"a":1,"why":"أكبر كواكب المجموعة الشمسية حجمًا المشتري، ولا يقاربه المريخ ولا الأرض ولا عطارد. فالأرض تأتي خامسة في الحجم.","ow":["المريخ أصغر من المشتري بكثير.","","الأرض أصغر من المشتري كثيرًا.","عطارد أصغر الكواكب حجمًا."]},
  {"q":"أصغر كواكب المجموعة الشمسية حجمًا:","o":["عطارد","نبتون","زحل","المشتري"],"a":0,"why":"أصغر كواكب المجموعة الشمسية حجمًا عطارد، وهو أيضًا أقربها إلى الشمس. أما المشتري وزحل ونبتون فكواكب كبيرة.","ow":["","نبتون كوكب كبير الحجم.","زحل كوكب كبير الحجم.","المشتري أكبر الكواكب وليس أصغرها."]},
  {"q":"الكواكب القريبة من الشمس تكون شديدة:","o":["الرطوبة","الحرارة","البرودة"],"a":1,"why":"الكواكب القريبة من الشمس تكون شديدة الحرارة، والبعيدة عنها شديدة البرودة، وهذا بسبب تدبير الله في توزيع المسافات. وليست شديدة الرطوبة.","ow":["الرطوبة لا ترتبط بالقرب من الشمس.","","البرودة تكون للكواكب البعيدة لا القريبة."]},
  {"q":"جعل الله كوكب الأرض في المرتبة ... حجمًا:","o":["الثالثة","الأولى","الخامسة","الثامنة"],"a":2,"why":"جعل الله الأرض الخامسة حجمًا بين الكواكب والثالثة قربًا من الشمس، فحرارتها معتدلة. وليست الأولى ولا الثامنة حجمًا.","ow":["الثالثة هي ترتيب الأرض قربًا من الشمس وليس حجمًا.","الأولى حجمًا هي المشتري.","","الثامنة حجمًا هي عطارد."]},
  {"q":"القمر السعودي للاتصالات (SGS-1) أطلقته المملكة عام:","o":["1405 هـ","1300 هـ","1440 هـ"],"a":2,"why":"أطلقت المملكة القمر السعودي للاتصالات (SGS-1) عام 1440 هـ، وهو من إنجازات المملكة في الفضاء والاتصالات.","ow":["1405 هـ ليس تاريخ إطلاق SGS-1.","1300 هـ تاريخ قديم قبل تطور الأقمار الصناعية.",""]},
  {"q":"العبارة: الشمس كوكب يستمد الضوء من القمر.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: الشمس نجم يشع الحرارة والضوء بنفسها، وهي مصدر الضوء، أما القمر فيعكس ضوء الشمس ولا يعطي الشمس ضوءًا.","ow":["الصحيح أن الشمس نجم وليست كوكبًا يستمد الضوء، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: عدد كواكب المجموعة الشمسية ثمانية كواكب.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: عدد كواكب المجموعة الشمسية ثمانية كواكب تدور حول الشمس، أقربها عطارد وأبعدها نبتون.","ow":["","العبارة صحيحة، فالكواكب ثمانية."]},
  {"q":"العبارة: الكواكب تضيء بنفسها.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: الكواكب أجسام معتمة لا تضيء بنفسها، وتستمد الضوء والحرارة من الشمس. أما التي تضيء بنفسها فالنجوم.","ow":["الصحيح أن الكواكب معتمة، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: الأرض هي الكوكب الثالث قربًا من الشمس.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: الأرض هي الكوكب الثالث قربًا من الشمس، بعد عطارد ثم الزهرة، ولذلك حرارتها معتدلة.","ow":["","العبارة صحيحة، فترتيب الأرض الثالث."]},
  {"q":"العبارة: تنتمي مجموعتنا الشمسية إلى مجرة درب التبانة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: مجموعتنا الشمسية تنتمي إلى مجرة درب التبانة، وهي المجرة التي فيها الشمس والأرض.","ow":["","العبارة صحيحة، فمجرتنا هي درب التبانة."]}
];
window.BANK['so7']['so7-1-2'] = [
  {"q":"تبدو الأرض للإنسان منبسطة لأن ما يراه منها:","o":["صغير جدًا بالنسبة لمساحتها الحقيقية","مغطى بالماء","كبير جدًا"],"a":0,"why":"تبدو الأرض للإنسان منبسطة لأن ما يراه منها صغير جدًا بالنسبة لمساحتها الحقيقية، فلا يلاحظ الانحناء. وكأننا نرى جزءًا صغيرًا من كرة كبيرة.","ow":["","الماء ليس سبب ظهورها منبسطة.","ما يراه ليس كبيرًا، بل صغير جدًا بالنسبة للأرض كلها."]},
  {"q":"رأى رواد الفضاء الأرض بشكلها الكروي:","o":["مباشرة بعد أن صعدوا إلى الفضاء الخارجي","من قمم الجبال","من خلال الصور القديمة فقط"],"a":0,"why":"رأى رواد الفضاء الأرض بشكلها الكروي مباشرة بعد أن صعدوا إلى الفضاء الخارجي، فتأكد ما أثبته العلماء من قبل.","ow":["","قمم الجبال لا تكفي لرؤية الأرض كاملة.","الصور القديمة وحدها ليست الرؤية المباشرة التي ذكرها الدرس."]},
  {"q":"صعد الأمير سلطان بن سلمان إلى الفضاء على متن المركبة:","o":["أبولو","سويوز","ديسكفري"],"a":2,"why":"صعد الأمير سلطان بن سلمان إلى الفضاء على متن المركبة ديسكفري عام 1405هـ، وهو أول رائد فضاء عربي مسلم.","ow":["أبولو مركبة هبطت بها رحلات القمر الأمريكية.","سويوز مركبة روسية وليست التي صعد بها الأمير سلطان.",""]},
  {"q":"صعد أول رائد فضاء عربي مسلم إلى الفضاء عام:","o":["1405 هـ","1440 هـ","1300 هـ"],"a":0,"why":"صعد أول رائد فضاء عربي مسلم إلى الفضاء عام 1405هـ، أما 1440 هـ فعام إطلاق القمر السعودي SGS-1، و1300 هـ أقدم بكثير.","ow":["","1440 هـ عام إطلاق قمر الاتصالات السعودي.","1300 هـ قبل رحلات الفضاء بزمن طويل."]},
  {"q":"كان لعلماء المسلمين منذ قرون آراء تثبت:","o":["ثبات الشمس","انبساط الأرض","كروية الأرض"],"a":2,"why":"كان لعلماء المسلمين منذ قرون آراء تثبت كروية الأرض، وفسّروا الآيات القرآنية للدلالة على ذلك. فلم يقولوا بانبساطها.","ow":["ثبات الشمس ليس ما أثبته العلماء هنا.","انبساط الأرض ضد ما أثبته العلماء.",""]},
  {"q":"الأرض هي المكان الوحيد الذي توجد فيه ... بين كواكب الكون:","o":["الحياة","الشمس","المياه فقط"],"a":0,"why":"الأرض هي المكان الوحيد الذي توجد فيه الحياة بين سائر كواكب الكون، وهي مسكن ملايين الأنواع من الكائنات الحية.","ow":["","الشمس لا تسكنها الكائنات الحية.","الحياة لا تقتصر على المياه وحدها، فالأرض مكانها كله."]},
  {"q":"طول القطر الاستوائي للأرض:","o":["510 ملايين كم","12714 كم","12757 كم"],"a":2,"why":"القطر الاستوائي للأرض 12757 كم، وهو أطول من القطر القطبي 12714 كم. أما 510 ملايين كم فمساحة السطح بالكيلومتر المربع.","ow":["510 ملايين كم² هي مساحة السطح وليست قطرًا.","12714 كم هو القطر القطبي.",""]},
  {"q":"القطر الاستوائي هو الخط الوهمي المستقيم الواصل بين:","o":["مكة والمدينة","القطبين","أبعد نقطتين على خط الاستواء والمار بمركز الأرض"],"a":2,"why":"القطر الاستوائي هو الخط الوهمي المستقيم الواصل بين أبعد نقطتين على خط الاستواء والمار بمركز الأرض.","ow":["مكة والمدينة مدينتان وليستا نقطتين على الاستواء.","الخط الواصل بين القطبين هو القطر القطبي.",""]},
  {"q":"الأرض مفلطحة عند:","o":["القطبين","خط جرينتش","خط الاستواء"],"a":0,"why":"الأرض مفلطحة عند القطبين، أي مضغوطة قليلًا، ومنبعجة عند خط الاستواء. وهذا يجعل القطر القطبي أقصر.","ow":["","خط جرينتش ليس مكان التفلطح.","عند خط الاستواء تنبعج الأرض لا تتفلطح."]},
  {"q":"أي القطرين أقصر؟","o":["القطر الاستوائي","متساويان","القطر القطبي"],"a":2,"why":"القطر القطبي هو الأقصر، فهو 12714 كم أما القطر الاستوائي فهو 12757 كم. فالفرق نحو 43 كم.","ow":["القطر الاستوائي أطول لا أقصر.","القطران غير متساويين.",""]},
  {"q":"يمتد محور الأرض القطبي من:","o":["الشرق إلى الشمال","الشمال إلى الجنوب","الشرق إلى الغرب"],"a":1,"why":"يمتد محور الأرض القطبي من الشمال إلى الجنوب، فهو يصل بين القطبين الشمالي والجنوبي ويمر بمركز الأرض.","ow":["الاتجاه من الشرق إلى الشمال ليس اتجاه المحور القطبي.","","الشرق إلى الغرب هو اتجاه خط الاستواء."]},
  {"q":"الخط الوهمي الواصل بين القطبين والمار بمركز الأرض يسمى:","o":["القطر الاستوائي","القطر القطبي","خط الطول"],"a":1,"why":"الخط الوهمي الواصل بين القطبين والمار بمركز الأرض هو القطر القطبي، أما الاستوائي فيصل بين نقطتين على خط الاستواء.","ow":["القطر الاستوائي يصل بين نقطتين على الاستواء.","","خط الطول يمتد على سطح الأرض بين القطبين فقط."]},
  {"q":"أبعاد الأرض:","o":["متساوية","ثابتة بلا فرق","غير متساوية"],"a":2,"why":"أبعاد الأرض غير متساوية، فالقطر الاستوائي أطول من القطبي، ولهذا هي ليست كاملة الاستدارة.","ow":["لو كانت متساوية لكانت الأرض كاملة الاستدارة، وهذا غير صحيح.","الفرق بين القطرين يدل على أن الأبعاد غير ثابتة بلا فرق.",""]},
  {"q":"الأرض مسكن لملايين الأنواع من:","o":["الشهب","المجرات","الكائنات الحية"],"a":2,"why":"الأرض مسكن لملايين الأنواع من الكائنات الحية، فهي المكان الوحيد الذي توجد فيه الحياة بين الكواكب.","ow":["الشهب أجسام تشتعل في الغلاف الجوي ولا تسكنها الكائنات.","المجرات أكبر بكثير من الأرض.",""]},
  {"q":"قديمًا لم يتمكن الإنسان من رؤية صورة شكل الأرض لأنه:","o":["كان يسكن الغابات","كانت الأرض مغطاة","لم يكن باستطاعته رؤية أكثر مما يصل إليه بصره"],"a":2,"why":"لم يتمكن الإنسان قديمًا من رؤية صورة شكل الأرض لأنه لم يكن باستطاعته رؤية أكثر مما يصل إليه بصره، فلم يرَ الانحناء.","ow":["سكناه الغابات لا علاقة له برؤية الشكل.","الأرض لم تكن مغطاة ولا تحجب رؤيتها.",""]},
  {"q":"العبارة: أبعاد الأرض متساوية.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: أبعاد الأرض غير متساوية، فالقطر الاستوائي 12757 كم أطول من القطبي 12714 كم، فهي منبعجة عند الاستواء.","ow":["الصحيح أن الأبعاد غير متساوية، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: القطر القطبي أطول من القطر الاستوائي.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: القطر القطبي أقصر من القطر الاستوائي، فالأول 12714 كم والثاني 12757 كم.","ow":["الصحيح أن القطر القطبي أقصر، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: الأرض هي المكان الوحيد الذي توجد فيه الحياة بين كواكب الكون.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: الأرض هي المكان الوحيد المعروف الذي توجد فيه الحياة بين كواكب الكون، وهي مسكن ملايين الكائنات.","ow":["","العبارة صحيحة، فهذا ما ذكره الدرس."]},
  {"q":"العبارة: الأمير سلطان بن سلمان أول رائد فضاء عربي مسلم.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: الأمير سلطان بن سلمان أول رائد فضاء عربي مسلم، صعد على المركبة ديسكفري عام 1405هـ.","ow":["","العبارة صحيحة، فهو أول رائد عربي مسلم."]},
  {"q":"العبارة: القطر القطبي خط وهمي يصل بين القطبين ويمر بمركز الأرض.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: القطر القطبي خط وهمي مستقيم يصل بين القطبين ويمر بمركز الأرض، ويبلغ طوله 12714 كم.","ow":["","العبارة صحيحة، فهذا تعريف القطر القطبي."]}
];
window.BANK['so7']['so7-1-3'] = [
  {"q":"سُمّيت شبكة الخطوط الوهمية التي ترسم على الخرائط:","o":["المدارات","الأقاليم","خطوط الطول ودوائر العرض (الإحداثيات)"],"a":2,"why":"شبكة الخطوط الوهمية التي ترسم على الخرائط تسمى خطوط الطول ودوائر العرض أو الإحداثيات، وبها نحدد المواقع بدقة.","ow":["المدارات هي بعض دوائر العرض فقط.","الأقاليم مناطق مناخية وليست شبكة خطوط.",""]},
  {"q":"خطوط الطول هي خطوط وهمية طولية تمتد من:","o":["خط الاستواء إلى مدار السرطان","الشرق إلى الغرب","القطب الشمالي إلى القطب الجنوبي"],"a":2,"why":"خطوط الطول خطوط وهمية تمتد من القطب الشمالي إلى القطب الجنوبي، وهي أنصاف دوائر تلتقي في القطبين.","ow":["خط الاستواء إلى مدار السرطان ليس امتداد خطوط الطول.","الشرق إلى الغرب هو امتداد دوائر العرض.",""]},
  {"q":"خطوط الطول:","o":["أنصاف دوائر متساوية في الطول","خطوط متوازية لا تلتقي","دوائر كاملة غير متساوية"],"a":0,"why":"خطوط الطول أنصاف دوائر متساوية في الطول وتلتقي في القطبين، أما دوائر العرض فكاملة وغير متساوية ومتوازية.","ow":["","الخطوط المتوازية التي لا تلتقي هي دوائر العرض.","الدوائر الكاملة غير المتساوية هي دوائر العرض."]},
  {"q":"جرينتش بلدة تقع إلى الجنوب الشرقي من مدينة:","o":["لندن","الرياض","القاهرة"],"a":0,"why":"جرينتش بلدة تقع جنوب شرق لندن عاصمة بريطانيا، ومنها يمر الخط الرئيس لخطوط الطول بدرجة صفر.","ow":["","الرياض لا يمر بها خط جرينتش.","القاهرة لا يمر بها خط جرينتش."]},
  {"q":"عدد خطوط الطول شرق جرينتش:","o":["24","360","180","90"],"a":2,"why":"عدد خطوط الطول شرق جرينتش 180 خطًا، ومثلها غربه، فالمجموع 360 خطًا. أما 24 فعدد المناطق الزمنية و90 عدد دوائر العرض في جهة واحدة.","ow":["24 عدد المناطق الزمنية.","360 عدد الخطوط كلها وليس في جهة واحدة.","","90 عدد دوائر العرض في جهة واحدة."]},
  {"q":"كم يبلغ الفارق الزمني لشروق الشمس بين خطي طول متتاليين؟","o":["4 دقائق","ساعة","10 دقائق","15 دقيقة"],"a":0,"why":"الفارق الزمني بين خطي طول متتاليين 4 دقائق، لأن الأرض تدور درجة واحدة كل 4 دقائق. وبين كل 15 خطًا ساعة كاملة.","ow":["","ساعة هو فارق 15 خطًا.","10 دقائق ليس الرقم الصحيح.","15 دقيقة ليس الفارق بين خطين."]},
  {"q":"يتقدم وقت شروق الشمس في الأماكن التي تقع ... خط جرينتش:","o":["غرب","على","شرق"],"a":2,"why":"يتقدم الشروق في الأماكن التي تقع شرق خط جرينتش لأن الأرض تدور من الغرب إلى الشرق، فتصل الشمس الشرق أولًا.","ow":["غرب جرينتش يتأخر شروق الشمس.","على الخط نفسه يكون الوقت هو توقيت جرينتش.",""]},
  {"q":"قُسّمت دول العالم إلى ... منطقة زمنية:","o":["اثنتي عشرة","أربع وعشرين","ستين"],"a":1,"why":"قُسمت دول العالم إلى 24 منطقة زمنية، كل منها ساعة واحدة، فتتوافق كل منطقة مع 15 خطًا من خطوط الطول.","ow":["اثنتا عشرة هي نصف عدد المناطق الزمنية، فالعدد الصحيح أربع وعشرون.","","ستون ليس عدد المناطق الزمنية."]},
  {"q":"كل منطقة زمنية تعادل:","o":["15 درجة طولية (ساعة)","180 درجة","4 دقائق"],"a":0,"why":"كل منطقة زمنية تعادل 15 درجة طولية أي ساعة زمنية واحدة، ويتفق ذلك مع 4 دقائق لكل درجة.","ow":["","180 درجة نصف الكرة الأرضية.","4 دقائق هي الفارق بين خطين وليس منطقة زمنية."]},
  {"q":"دوائر العرض دوائر كاملة:","o":["تلتقي في القطبين","متوازية وغير متساوية في الطول","متساوية في الطول"],"a":1,"why":"دوائر العرض دوائر كاملة متوازية وغير متساوية في الطول، فأكبرها خط الاستواء وكلما اتجهنا نحو القطبين صغرت.","ow":["لا تلتقي في القطبين، فذلك لخطوط الطول.","","ليست متساوية في الطول."]},
  {"q":"عدد دوائر العرض:","o":["180","90","360"],"a":0,"why":"عدد دوائر العرض 180 دائرة: 90 شمال خط الاستواء و90 جنوبه. أما 360 فهو عدد خطوط الطول، و90 هو عدد الدوائر في جهة واحدة فقط.","ow":["","90 عدد الدوائر في جهة واحدة.","360 عدد خطوط الطول."]},
  {"q":"تقسم دائرة الاستواء الأرض إلى قسمين:","o":["شمالي وجنوبي","حار وبارد","شرقي وغربي"],"a":0,"why":"دائرة الاستواء تقسم الأرض إلى نصفين متساويين: شمالي وجنوبي، أما الشرقي والغربي فيحددهما خط جرينتش.","ow":["","الحار والبارد ليسا نصفين متساويين.","شرقي وغربي يحددهما خط جرينتش لا الاستواء."]},
  {"q":"درجة مدار السرطان:","o":["23.5 جنوب خط الاستواء","23.5 شمال خط الاستواء","66.5 شمالًا"],"a":1,"why":"مدار السرطان عند 23.5 درجة شمال خط الاستواء، أما المدار الجنوبي فهو مدار الجدي عند 23.5 جنوبًا. فلا تخلطهما مع الدائرة القطبية عند 66.5.","ow":["23.5 جنوبًا هو مدار الجدي.","","66.5 شمالًا هي الدائرة القطبية الشمالية."]},
  {"q":"درجة الدائرة القطبية الشمالية:","o":["66.5 شمال خط الاستواء","23.5 شمالًا","90 شمالًا"],"a":0,"why":"الدائرة القطبية الشمالية عند 66.5 درجة شمال خط الاستواء، وبعدها المنطقة الباردة الشمالية.","ow":["","23.5 شمالًا هو مدار السرطان.","90 شمالًا هو القطب الشمالي نفسه."]},
  {"q":"المنطقتان المعتدلتان تمتدان بين دائرتي العرض:","o":["66.5 و90","23.5 و66.5 شمالًا وجنوبًا","صفر و23.5"],"a":1,"why":"المنطقتان المعتدلتان تمتدان بين دائرتي العرض 23.5 و66.5 شمالًا وجنوبًا، فهما بين الحارة والباردة.","ow":["66.5 و90 هما المنطقتان الباردتان.","","صفر و23.5 جزء من المنطقة الحارة."]},
  {"q":"المنطقتان الباردتان تمتدان بين دائرتي العرض:","o":["66.5 و90 شمالًا وجنوبًا","23.5 و66.5","صفر و23.5"],"a":0,"why":"المنطقتان الباردتان تمتدان من 66.5 إلى 90 درجة شمالًا وجنوبًا، أي حول القطبين. أما بين 23.5 و66.5 فالمنطقتان المعتدلتان.","ow":["","بين 23.5 و66.5 منطقتان معتدلتان.","بين صفر و23.5 جزء من المنطقة الحارة."]},
  {"q":"العبارة: خطوط الطول تفيد في معرفة الزمن في مختلف جهات الأرض.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: خطوط الطول تفيد في تحديد المواقع ومعرفة الزمن في مختلف جهات الأرض، لأن بين كل خطين 4 دقائق.","ow":["","العبارة صحيحة، فهذه فائدة خطوط الطول."]},
  {"q":"العبارة: دوائر العرض تفيد في معرفة المناطق الحرارية.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: دوائر العرض تفيد في معرفة المناطق الحرارية: الحارة والمعتدلة والباردة.","ow":["","العبارة صحيحة، فهذه فائدة دوائر العرض."]},
  {"q":"العبارة: الخط الرئيس لدوائر العرض يسمى خط جرينتش.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: الخط الرئيس لدوائر العرض هو دائرة الاستواء، أما جرينتش فهو الخط الرئيس لخطوط الطول.","ow":["الصحيح أن جرينتش لخطوط الطول، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: المنطقة الحارة تقع بين مداري السرطان والجدي ويمر وسطها خط الاستواء.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: المنطقة الحارة بين مدار السرطان ومدار الجدي، ويمر في وسطها خط الاستواء.","ow":["","العبارة صحيحة، فهذا موقع المنطقة الحارة."]}
];
window.BANK['so7']['so7-1-4'] = [
  {"q":"تتحرك الأرض حركة:","o":["منتظمة وفق نظام محكم","عشوائية","متوقفة"],"a":0,"why":"تتحرك الأرض حركة منتظمة وفق نظام محكم من صنع الله، فلا تتوقف ولا تضطرب، ولذلك يتعاقب الليل والنهار بانتظام.","ow":["","الحركة ليست عشوائية بل منظمة.","الأرض لا تتوقف، فهي تدور دائمًا."]},
  {"q":"من أسباب عدم شعورنا بحركة الأرض:","o":["قلة سرعتها فقط","كبر حجمها ووجود الجاذبية","ثباتها"],"a":1,"why":"لا نشعر بحركة الأرض لكبر حجمها ووجود الجاذبية، وهي تدور بما فيها مع غلافها الجوي، كالطائرة التي لا يشعر ركابها بحركتها.","ow":["قلة السرعة وحدها ليست السبب، فالأرض سريعة جدًا.","","الأرض ليست ثابتة، بل تتحرك."]},
  {"q":"تدور الأرض حول محورها دورة كاملة كل:","o":["365 يومًا","12 ساعة","24 ساعة","شهر"],"a":2,"why":"تدور الأرض حول محورها دورة كاملة كل 24 ساعة، وهذه هي الحركة اليومية التي تعطينا اليوم الكامل.","ow":["365 يومًا مدة دورانها حول الشمس.","12 ساعة نصف اليوم فقط.","","الشهر ليس مدة دورانها حول محورها."]},
  {"q":"تدور الأرض حول الشمس دورة كاملة في نحو:","o":["365 يومًا وربع","30 يومًا","24 ساعة"],"a":0,"why":"تدور الأرض حول الشمس دورة كاملة في نحو 365 يومًا وربع، فهذه هي السنة. وتحتاج السنة الكبيسة لإضافة يوم كل أربع سنوات.","ow":["","30 يومًا مدة الشهر تقريبًا.","24 ساعة مدة دورانها حول محورها."]},
  {"q":"تدور الأرض حول محورها في اتجاه:","o":["من الشمال إلى الجنوب","من الشرق إلى الغرب","من الغرب إلى الشرق"],"a":2,"why":"تدور الأرض حول محورها من الغرب إلى الشرق، ولهذا نرى الشمس تشرق من الشرق وتغرب في الغرب.","ow":["الاتجاه من الشمال إلى الجنوب ليس اتجاه الدوران.","الاتجاه من الشرق إلى الغرب عكس الصحيح.",""]},
  {"q":"تعاقب الليل والنهار نتيجة لحركة الأرض:","o":["حول القمر","حول الشمس","حول محورها"],"a":2,"why":"تعاقب الليل والنهار نتيجة حركة الأرض حول محورها، فالجزء المواجه للشمس نهار والجزء الآخر ليل.","ow":["القمر لا تدور الأرض حوله.","الدوران حول الشمس يسبب الفصول.",""]},
  {"q":"اختلاف الزمن على سطح الأرض ينتج عن حركة الأرض:","o":["حول القمر","حول محورها","حول الشمس"],"a":1,"why":"اختلاف الزمن على سطح الأرض ينتج عن حركتها حول محورها، فبعض الأماكن تواجه الشمس بينما أخرى في الظلام.","ow":["الأرض لا تدور حول القمر.","","الدوران حول الشمس يسبب الفصول وليس اختلاف الزمن."]},
  {"q":"أي مما يأتي من نتائج الحركة اليومية للأرض؟","o":["الفصول الأربعة","اختلاف طول السنة","انحراف الرياح والتيارات المائية"],"a":2,"why":"من نتائج الحركة اليومية انحراف الرياح والتيارات المائية، أما الفصول واختلاف طول السنة فمن نتائج الحركة السنوية.","ow":["الفصول الأربعة نتيجة الحركة السنوية.","اختلاف طول السنة ليس من نتائج الحركة اليومية.",""]},
  {"q":"الفصول الأربعة تنتج عن:","o":["دوران الأرض حول الشمس مع ميل محورها","دوران القمر","بعد الأرض عن القمر"],"a":0,"why":"الفصول الأربعة تنتج عن دوران الأرض حول الشمس مع ميل محورها، ومع ثبات الميل يتغير مقدار الحرارة في كل نصف.","ow":["","دوران القمر لا يسبب الفصول.","بعد الأرض عن القمر لا يسبب الفصول."]},
  {"q":"يميل محور الأرض القطبي بمقدار:","o":["23.5 درجة","66.5 درجة","90 درجة"],"a":0,"why":"يميل محور الأرض القطبي بمقدار 23.5 درجة عن الخط العمودي، وهو سبب الفصول مع دوران الأرض حول الشمس.","ow":["","66.5 درجة هي درجة الدائرتين القطبيتين.","90 درجة ليست مقدار الميل."]},
  {"q":"تتعامد الشمس على خط الاستواء يوم:","o":["21 مارس","22 ديسمبر","21 يونيو"],"a":0,"why":"تتعامد الشمس على خط الاستواء يوم 21 مارس ثم 23 سبتمبر، فيتساوى الليل والنهار تقريبًا في أنحاء الأرض.","ow":["","22 ديسمبر تتعامد على مدار الجدي.","21 يونيو تتعامد على مدار السرطان."]},
  {"q":"تتعامد الشمس على مدار الجدي يوم:","o":["21 يونيو","21 مارس","22 ديسمبر"],"a":2,"why":"تتعامد الشمس على مدار الجدي يوم 22 ديسمبر، فيحل الصيف في الجنوب والشتاء في الشمال.","ow":["21 يونيو تتعامد على مدار السرطان.","21 مارس تتعامد على خط الاستواء.",""]},
  {"q":"يوم 21 يونيو يكون في نصف الأرض الشمالي فصل:","o":["الصيف","الربيع","الخريف","الشتاء"],"a":0,"why":"يوم 21 يونيو تتعامد الشمس على مدار السرطان فيحل الصيف في نصف الأرض الشمالي، أما الجنوبي فيكون شتاؤه.","ow":["","الربيع يبدأ شمالًا يوم 21 مارس.","الخريف يبدأ شمالًا يوم 23 سبتمبر.","الشتاء شمالًا يبدأ يوم 22 ديسمبر."]},
  {"q":"يوم 23 سبتمبر يكون في نصف الأرض الشمالي فصل:","o":["الخريف","الربيع","الصيف"],"a":0,"why":"يوم 23 سبتمبر تتعامد الشمس على خط الاستواء فيحل الخريف في النصف الشمالي، ويبدأ الربيع في الجنوبي.","ow":["","الربيع شمالًا يبدأ يوم 21 مارس.","الصيف شمالًا يبدأ يوم 21 يونيو."]},
  {"q":"عندما يكون الصيف في نصف الأرض الشمالي يكون في الجنوبي:","o":["الشتاء","الربيع","الصيف"],"a":0,"why":"الفصلان متعاكسان في نصفي الأرض، فحين يكون الصيف في الشمالي يكون الشتاء في الجنوبي لأن الشمس تتعامد على أحدهما دون الآخر.","ow":["","الربيع لا يتعاكس مع الصيف في هذه الحالة.","الصيف في النصفين معًا غير ممكن لاختلاف تعامد الشمس."]},
  {"q":"العبارة: ثبات ميل المحور في اتجاه واحد أثناء الدوران يسبب الفصول.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: ثبات ميل المحور في اتجاه واحد أثناء الدوران حول الشمس يسبب الفصول، فتتغير كمية الحرارة في كل نصف.","ow":["","العبارة صحيحة، فالميل والدوران معًا يسببان الفصول."]},
  {"q":"العبارة: تدور الأرض حول الشمس كل 24 ساعة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: تدور الأرض حول الشمس في 365 يومًا وربع، أما 24 ساعة فمدة دورانها حول محورها.","ow":["الصحيح أن 24 ساعة لدورانها حول محورها، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: تدور الأرض بما فيها مع غلافها الجوي.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: تدور الأرض بما فيها وبغلافها الجوي، ولهذا لا نشعر بحركتها ولا تتحرك الغيوم بعيدًا عنا.","ow":["","العبارة صحيحة، فالغلاف الجوي يدور مع الأرض."]},
  {"q":"العبارة: يحل الربيع في نصف الأرض الشمالي يوم 21 مارس.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: يحل الربيع في النصف الشمالي يوم 21 مارس لأن الشمس تتعامد على خط الاستواء.","ow":["","العبارة صحيحة، فالربيع يبدأ شمالًا يوم 21 مارس."]},
  {"q":"العبارة: يحل الشتاء في نصف الأرض الشمالي يوم 21 يونيو.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: يوم 21 يونيو يحل الصيف في النصف الشمالي، لأن الشمس تتعامد على مدار السرطان، والشتاء يكون جنوبًا.","ow":["الصحيح أن الصيف شمالًا في هذا اليوم، فالعبارة غير صحيحة.",""]}
];
window.BANK['so7']['so7-1-5'] = [
  {"q":"سطح الأرض يتكون من:","o":["مرتفعات ومنخفضات كبرى","سهول فقط","جبال فقط"],"a":0,"why":"سطح الأرض هو كل ما عليها من مرتفعات ومنخفضات كبرى، فلا يقتصر على السهول أو الجبال وحدها، بل يضم الاثنين معًا.","ow":["","السهول وحدها جزء من سطح الأرض فقط.","الجبال وحدها جزء من سطح الأرض فقط."]},
  {"q":"تكوّن سطح الأرض بأمر الله بعوامل:","o":["بشرية فقط","ظاهرية فقط","باطنية وظاهرية"],"a":2,"why":"تكوّن سطح الأرض بأمر الله بعوامل باطنية، أي من داخل الأرض، وظاهرية، أي من خارجها كالرياح والمياه، فهما معًا.","ow":["العوامل ليست بشرية فقط.","العوامل ليست ظاهرية فقط، فهناك أيضًا عوامل باطنية.",""]},
  {"q":"نسبة اليابسة من مساحة سطح الأرض نحو:","o":["71%","10%","50%","29%"],"a":3,"why":"نسبة اليابسة نحو 29% من مساحة سطح الأرض، والباقي 71% ماء. فلا تساوي اليابسة 50% ولا 71% ولا 10%.","ow":["71% هي نسبة الماء.","10% أقل بكثير من نسبة اليابسة.","50% ليست النسبة الصحيحة.",""]},
  {"q":"تنقسم اليابسة إلى سبع كتل كبرى تسمى:","o":["جزرًا","محيطات","قارات"],"a":2,"why":"تنقسم اليابسة إلى سبع كتل كبرى تسمى قارات. أما الجزر فقطع صغيرة محاطة بالماء، والمحيطات مسطحات مائية.","ow":["الجزر أصغر بكثير من القارات.","المحيطات من الماء وليست من اليابسة.",""]},
  {"q":"أي من الآتي ليس من القارات؟","o":["إفريقيا","المحيط الهادئ","أستراليا","أوروبا"],"a":1,"why":"المحيط الهادئ ليس قارة بل مسطح مائي واسع، أما إفريقيا وأستراليا وأوروبا فقارات من القارات السبع.","ow":["إفريقيا قارة من القارات السبع.","","أستراليا قارة من القارات السبع.","أوروبا قارة من القارات السبع."]},
  {"q":"القارة التي تقع فيها المملكة العربية السعودية:","o":["إفريقيا","أوروبا","آسيا"],"a":2,"why":"تقع المملكة العربية السعودية في قارة آسيا، وهي أكبر القارات مساحة، في جنوبها الغربي.","ow":["إفريقيا غرب البحر الأحمر وليست فيها المملكة.","أوروبا شمال غرب بعيدة عن المملكة.",""]},
  {"q":"أي مما يأتي من القارات السبع؟","o":["أمريكا الجنوبية","البحر الأحمر","المحيط الأطلسي"],"a":0,"why":"أمريكا الجنوبية من القارات السبع، أما البحر الأحمر فمسطح مائي والمحيط الأطلسي أحد المحيطات.","ow":["","البحر الأحمر ليس قارة، بل بحر.","المحيط الأطلسي مسطح مائي وليس قارة."]},
  {"q":"أعلى قمة جبلية في العالم هي قمة:","o":["إيفرست","طويق","السودة"],"a":0,"why":"أعلى قمة جبلية في العالم قمة إيفرست في جبال الهيمالايا، يبلغ ارتفاعها نحو 8850 م. أما طويق والسودة فجبال في المملكة أقل ارتفاعًا.","ow":["","طويق جبال في نجد أقل ارتفاعًا بكثير.","السودة أعلى قمة في المملكة لا في العالم."]},
  {"q":"جبال الهيمالايا تقع في:","o":["شمالي الهند","جنوب إفريقيا","أوروبا"],"a":0,"why":"جبال الهيمالايا تقع في شمالي الهند، وفيها قمة إيفرست أعلى قمم العالم. وليست في إفريقيا ولا أوروبا.","ow":["","جنوب إفريقيا ليس فيها الهيمالايا.","أوروبا فيها جبال الألب لا الهيمالايا."]},
  {"q":"ارتفاع قمة إيفرست نحو:","o":["885 م","88500 م","8850 م"],"a":2,"why":"يبلغ ارتفاع قمة إيفرست نحو 8850 م فوق مستوى سطح البحر. أما 885 م فأقل بعشر مرات و88500 م أكبر بعشر مرات.","ow":["885 م أقل بكثير من ارتفاعها.","88500 م أكبر بكثير من ارتفاعها.",""]},
  {"q":"أي مما يأتي منطقة منخفضة تحت مستوى سطح البحر؟","o":["جبال طويق","البحر الميت","جبل أحد"],"a":1,"why":"البحر الميت في غور الأردن منطقة منخفضة تحت مستوى سطح البحر. أما طويق وأحد فمرتفعان.","ow":["جبال طويق مرتفعة وليست تحت مستوى البحر.","","جبل أحد مرتفع وليس منخفضًا."]},
  {"q":"ينقسم الماء على سطح الأرض إلى ... مسطحات واسعة تسمى محيطات:","o":["سبعة","خمسة","ثلاثة"],"a":1,"why":"ينقسم الماء إلى خمسة مسطحات واسعة تسمى محيطات. أما سبعة فهو عدد القارات وثلاثة أقل من الحقيقي.","ow":["سبعة هو عدد القارات.","","ثلاثة أقل من عدد المحيطات."]},
  {"q":"المحيط هو مسطح مائي:","o":["ضحل صغير","عذب صغير","مالح واسع عميق"],"a":2,"why":"المحيط مسطح مائي مالح واسع عميق يحيط بكتل اليابسة. فهو ليس ضحلًا صغيرًا ولا عذبًا.","ow":["المسطح الضحل الصغير ليس محيطًا.","المسطح العذب الصغير ليس محيطًا.",""]},
  {"q":"من المحيطات:","o":["الميت","الهندي","الأحمر"],"a":1,"why":"المحيط الهندي من المحيطات الخمسة، أما الميت والأحمر فمسطحان مائيان أصغر ويسميان بحرًا.","ow":["البحر الميت ليس محيطًا.","","البحر الأحمر ليس محيطًا."]},
  {"q":"المحيط الأكبر مساحة:","o":["الأطلسي","الهندي","الهادئ"],"a":2,"why":"المحيط الهادئ هو الأكبر مساحة بين المحيطات الخمسة، أما الأطلسي والهندي فأصغر منه.","ow":["الأطلسي ثاني الأكبر.","الهندي ثالث الأكبر.",""]},
  {"q":"العبارة: الماء أكثر من ثلثي مساحة سطح الأرض.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: يغطي الماء 71% من مساحة سطح الأرض، وهي نسبة أكبر من ثلثي المساحة، أما اليابسة فتشغل 29% فقط.","ow":["","العبارة صحيحة، فالماء أكثر من ثلثي مساحة الأرض."]},
  {"q":"العبارة: أستراليا أكبر القارات مساحة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: آسيا هي أكبر القارات مساحة، أما أستراليا فهي أصغر القارات السبع، فلا تخلط بين الأكبر والأصغر.","ow":["الصحيح أن أستراليا أصغر القارات، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: عدد المحيطات خمسة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: عدد المحيطات خمسة: الهادئ والأطلسي والهندي والمتجمد الجنوبي والمتجمد الشمالي.","ow":["","العبارة صحيحة، فالمحيطات خمسة."]},
  {"q":"العبارة: المحيط المتجمد الشمالي هو الأصغر مساحة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: المحيط المتجمد الشمالي هو أصغر المحيطات الخمسة مساحة، أما المحيط الهادئ فهو الأكبر من بينها جميعًا.","ow":["","العبارة صحيحة، فهو أصغر المحيطات."]},
  {"q":"العبارة: ارتفاع اليابسة متساوٍ في جميع الأماكن.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: ارتفاع اليابسة يتباين من مكان لآخر، فهناك جبال شاهقة كإيفرست ومناطق منخفضة كالبحر الميت.","ow":["الصحيح أن الارتفاع يتباين، فالعبارة غير صحيحة.",""]}
];
window.BANK['so7']['so7-2-1'] = [
  {"q":"الحضارة هي تفاعل المجموعات البشرية مع:","o":["الدول الأخرى فقط","الحيوانات فقط","البيئات المحيطة بهم، وما ينتج عنه من أثر ديني أو فكري أو اجتماعي أو عمراني أو سياسي"],"a":2,"why":"الحضارة هي تفاعل المجموعات البشرية مع البيئات المحيطة بهم، وما ينتج عنه من أثر ديني أو فكري أو اجتماعي أو عمراني أو سياسي.","ow":["الحضارة ليست تفاعلًا مع الدول الأخرى فقط.","الحضارة ليست تفاعلًا مع الحيوانات فقط.",""]},
  {"q":"أخبر الله ملائكته بأنه سيخلق بشرًا من:","o":["نور","طين","ماء","نار"],"a":1,"why":"أخبر الله ملائكته أنه سيخلق بشرًا من طين خليفة له في الأرض، فخلق آدم عليه السلام من طين.","ow":["لم يُخلق البشر من نور، فالنور للملائكة.","","لم يُخلق البشر من ماء فقط.","لم يُخلق البشر من نار، فالنار للجن."]},
  {"q":"ذكر بعض المؤرخين أن آدم وحواء أُهبطا إلى الأرض في أرض:","o":["الشام","مصر","مكة المكرمة"],"a":2,"why":"ذكر بعض المؤرخين أن آدم وحواء أُهبطا إلى الأرض في أرض مكة المكرمة، حيث الكعبة أول بيت وُضع للناس.","ow":["الشام ليست أرض هبوطهما في ما ذكره الكتاب.","مصر ليست أرض هبوطهما في ما ذكره الكتاب.",""]},
  {"q":"شبه الجزيرة العربية تُعد:","o":["صحراء بلا حضارات","مهد الحضارات","منطقة جليدية"],"a":1,"why":"تُعد شبه الجزيرة العربية مهد الحضارات، فمنها كانت الهجرات إلى بقاع الأرض ونشأت حضارات كثيرة.","ow":["ليست صحراء بلا حضارات، فقد قامت عليها حضارات.","","ليست منطقة جليدية، فمناخها حار وجاف."]},
  {"q":"يساعد المناخ المعتدل على:","o":["هجرة السكان","تدمير المدن","نمو المحصولات الزراعية والأنشطة الاقتصادية"],"a":2,"why":"المناخ المعتدل يساعد على نمو المحاصيل الزراعية والأنشطة الاقتصادية، فتستقر المجموعات البشرية وتبني حضارتها.","ow":["المناخ المعتدل لا يدفع إلى هجرة السكان.","المناخ المعتدل لا يدمر المدن.",""]},
  {"q":"فترة الحضارة النبطية:","o":["100 ق.م - 300 م","1600 ق.م - 1046 ق.م","3500 ق.م - 500 ق.م"],"a":0,"why":"امتدت الحضارة النبطية من 100 ق.م إلى 300 م، أما 1600–1046 ق.م فهي فترة أسرة شانغ في الصين، و3500 ق.م ليست فترة الأنباط.","ow":["","1600 ق.م - 1046 ق.م فترة أسرة شانغ الصينية.","3500 ق.م - 500 ق.م ليست فترة الأنباط."]},
  {"q":"الحجر مدينة نبطية تقع في:","o":["الأردن","العراق","العلا بالمملكة"],"a":2,"why":"الحجر مدينة نبطية تقع في العلا بالمملكة العربية السعودية، وهي المدينة الجنوبية الأساسية للأنباط.","ow":["الأردن فيها البتراء لا الحجر.","العراق ليس فيها الحجر النبطية.",""]},
  {"q":"تقع البتراء عاصمة الأنباط في:","o":["مصر","الأردن","العراق","سوريا"],"a":1,"why":"تقع البتراء عاصمة الأنباط في الأردن، وهي مدينة منحوتة في الصخر مشهورة. أما الحجر فمدينتهم الجنوبية وتقع في العلا بالمملكة.","ow":["مصر ليست موقع البتراء.","","العراق ليس فيه البتراء.","سوريا ليست موقع البتراء."]},
  {"q":"اشتهر الأنباط بقدرتهم على إدارة:","o":["مصانع حديثة","شبكة تجارية واسعة","مدارس"],"a":1,"why":"اشتهر الأنباط بإدارة شبكة تجارية واسعة، إذ سيطروا على طريق البخور مدة طويلة. فلم تكن لهم مصانع حديثة ولا مدارس بالمعنى الحالي.","ow":["لم تكن لهم مصانع حديثة في ذلك الزمن.","","لم تُعرف بالمدارس كما نعرفها اليوم."]},
  {"q":"نشأت حضارة بلاد الرافدين في بلاد:","o":["الصين","ما بين النهرين في العراق","الجزيرة العربية فقط"],"a":1,"why":"نشأت حضارة بلاد الرافدين بين نهري دجلة والفرات في العراق، وقامت على الزراعة وقنوات الري.","ow":["الصين حضارتها على النهر الأصفر.","","لم تنشأ في الجزيرة العربية فقط، بل في العراق."]},
  {"q":"من أشهر مدن السومريين:","o":["أور ونيبور","مكة والمدينة","آشور ونينوى"],"a":0,"why":"من أشهر مدن السومريين أور ونيبور، أما آشور ونينوى فمدن الآشوريين ومكة والمدينة مدينتان في الجزيرة.","ow":["","مكة والمدينة ليستا من مدن السومريين.","آشور ونينوى مدينتان للآشوريين."]},
  {"q":"سُمي الأكاديون بهذا الاسم نسبة إلى مدينتهم:","o":["أكاد","بابل","أور"],"a":0,"why":"سُمي الأكاديون بهذا الاسم نسبة إلى مدينتهم أكاد، أما بابل فمدينة العموريين وأور مدينة سومرية.","ow":["","بابل مدينة العموريين.","أور مدينة السومريين."]},
  {"q":"بنى زعيم العموريين سامو آبي مدينة:","o":["أور","بابل","نينوى"],"a":1,"why":"بنى سامو آبي زعيم العموريين مدينة بابل وأسس الدولة البابلية الأولى، ثم جاء بعده حمورابي.","ow":["أور مدينة سومرية.","","نينوى مدينة آشورية."]},
  {"q":"تتكون قوانين حمورابي من:","o":["2820 قانونًا","28 قانونًا","282 قانونًا"],"a":2,"why":"تتكون قوانين حمورابي من 282 قانونًا، وهي من أقدم القوانين المكتوبة. أما 2820 أو 28 فرقمان غير صحيحين.","ow":["2820 أكبر بعشر مرات من العدد الصحيح.","28 أقل بكثير من العدد الصحيح.",""]},
  {"q":"من أشهر مدن الآشوريين:","o":["أور ونيبور","أكاد وبابل","آشور ونينوى"],"a":2,"why":"من أشهر مدن الآشوريين آشور ونينوى في شمال العراق، أما أور ونيبور فسومريتان وأكاد وبابل مدينتان أخريان.","ow":["أور ونيبور مدينتان سومريتان.","أكاد وبابل مدينتان أكاديتان وبابليتان.",""]},
  {"q":"العبارة: سيطر الأنباط على طريق البخور لمدة أربعمائة سنة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: سيطر الأنباط على طريق البخور نحو أربعمئة سنة، وهذا من أسباب ثرائهم وازدهار مدنهم.","ow":["","العبارة صحيحة، فقد سيطروا عليه أربعمئة سنة."]},
  {"q":"العبارة: بنى المصريون القدماء الأهرامات لدفن موتاهم.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: بنى المصريون القدماء الأهرامات لدفن موتاهم من الفراعنة، وهي من عجائب الدنيا.","ow":["","العبارة صحيحة، فالأهرامات مقابر الفراعنة."]},
  {"q":"العبارة: بُني سور الصين العظيم في القرن الثالث قبل الميلاد.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: ذكر الكتاب أن سور الصين العظيم بُني في القرن الثالث قبل الميلاد لحماية الحدود الشمالية من المغول.","ow":["","العبارة صحيحة بحسب ما ذكره الكتاب."]},
  {"q":"العبارة: معتقد (لاو تزو) في الصين يدعو إلى التفاعل الاجتماعي بين الناس.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: لاو تزو يدعو إلى الانعزال، أما الكونفوشية فتقوم على التفاعل الاجتماعي بين الناس.","ow":["الصحيح أن لاو تزو يدعو إلى الانعزال، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: يمتد تاريخ الصين القديمة أكثر من 4000 عام.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: يمتد تاريخ الصين القديمة أكثر من 4000 عام، من أسرة شانغ الأولى إلى أسرة تشينغ الأخيرة.","ow":["","العبارة صحيحة، فتاريخها يتجاوز 4000 عام."]}
];
window.BANK['so7']['so7-2-2'] = [
  {"q":"الأساس الثاني للحضارة الإسلامية هو الأساس:","o":["الصناعي","اللغوي","الديني"],"a":1,"why":"الأساس الثاني للحضارة الإسلامية الأساس اللغوي، وهو اللغة العربية لغة القرآن، يأتي بعد الأساس الديني الذي هو الأول.","ow":["الأساس الصناعي ليس من الأسس الأربعة.","","الأساس الديني هو الأول وليس الثاني."]},
  {"q":"تعد اللغة العربية أثرى اللغات لـ:","o":["كثرة مفرداتها ودقة تعبيراتها","قلة حروفها","سهولة كتابتها فقط"],"a":0,"why":"تعد العربية أثرى اللغات لكثرة مفرداتها ودقة تعبيراتها، ولذلك نزل بها القرآن. وليست قلة حروفها أو سهولة كتابتها وحدها سبب ذلك.","ow":["","قلة الحروف ليست سبب غناها.","سهولة الكتابة وحدها لا تكفي لوصفها بالأغنى."]},
  {"q":"يقوم الأساس العلمي على:","o":["الاستفادة من علوم الحضارات السابقة وتطويرها","ترك الدين","إهمال العلوم"],"a":0,"why":"الأساس العلمي يقوم على الاستفادة من علوم الحضارات السابقة وتطويرها، لا على ترك الدين ولا إهمال العلوم.","ow":["","ترك الدين ضد الأساس الديني.","إهمال العلوم ضد الأساس العلمي."]},
  {"q":"أي مما يأتي من الحضارات التي استفاد منها المسلمون؟","o":["الأمريكية","اليونانية","المغولية"],"a":1,"why":"استفاد المسلمون من الحضارات اليونانية والرومانية والهندية وطوّروا علومها، أما الأمريكية والمغولية فليستا مما ذكره الدرس.","ow":["الحضارة الأمريكية لم تكن بين الحضارات التي استفاد منها المسلمون.","","المغول لم يكونوا مصدر علوم الحضارة الإسلامية."]},
  {"q":"اتخذ الخلفاء الراشدون ... منهجًا في اختيار الحاكم:","o":["البيعة والشورى","القرعة","الوراثة"],"a":0,"why":"اتخذ الخلفاء الراشدون البيعة والشورى منهجًا في اختيار الحاكم، وهو منهج المملكة اليوم. فلم يختاروا بالقرعة أو الوراثة.","ow":["","القرعة ليست طريقة الخلفاء في الاختيار.","الوراثة لم تكن منهجهم."]},
  {"q":"اتخذ الخلفاء الأمويون من يستشيرونهم لكنهم لم يلقبوهم بلقب:","o":["ولاة","قضاة","وزراء"],"a":2,"why":"استشار الخلفاء الأمويون من يعاونهم لكنهم لم يلقبوهم بوزراء، فلقب الوزير ظهر لاحقًا في العصر العباسي.","ow":["لقب الولاة موجود في الدولة الأموية.","لقب القضاة موجود في الدولة الأموية.",""]},
  {"q":"وزارة التفويض هي أن:","o":["يفوّض الخليفة الوزير معظم شؤون الدولة","ينفذ الوزير أوامر الخليفة فقط","يعين الوزير القضاة فقط"],"a":0,"why":"وزارة التفويض أن يفوّض الخليفة الوزير في تصريف معظم شؤون الدولة، أما التنفيذ فينفذ أوامره فقط.","ow":["","هذا هو وزير التنفيذ.","تعيين القضاة فقط ليس تعريف وزارة التفويض."]},
  {"q":"القضاء هو:","o":["تعيين القضاة للفصل بين الناس في الخصومات","نقل الرسائل","جمع الأموال"],"a":0,"why":"القضاء هو تعيين القضاة للفصل بين الناس في الخصومات والنزاعات، أما نقل الرسائل فالبريد وجمع الأموال بيت المال.","ow":["","نقل الرسائل مهمة البريد.","جمع الأموال مهمة بيت المال."]},
  {"q":"الإمارة هي تعيين:","o":["الجنود","المعلمين","العمال والولاة على أجزاء البلاد الإسلامية"],"a":2,"why":"الإمارة هي تعيين العمال والولاة على أجزاء البلاد الإسلامية، فيحكم كل والٍ إقليمه باسم الخليفة.","ow":["تعيين الجنود من شؤون الجيش.","تعيين المعلمين ليس معنى الإمارة.",""]},
  {"q":"قسّم الخليفة عمر الدولة إلى:","o":["قبائل","أقاليم إدارية كبرى","مدن صغيرة فقط"],"a":1,"why":"قسّم الخليفة عمر الدولة إلى أقاليم إدارية كبرى وعيّن على كل قسم واليًا، لتنظيم الحكم بعد اتساع الدولة.","ow":["التقسيم لم يكن إلى قبائل.","","التقسيم لم يكن إلى مدن صغيرة فقط."]},
  {"q":"يعمل بيت المال على جمع:","o":["واردات الدولة وتنظيمها","الأسلحة","الرسائل"],"a":0,"why":"يعمل بيت المال على جمع واردات الدولة وتنظيمها، ويحقق التكافل الاجتماعي. أما الأسلحة والرسائل فلهما جهات أخرى.","ow":["","جمع الأسلحة ليس مهمة بيت المال.","الرسائل مهمة البريد."]},
  {"q":"ديوان الجند تُحدد فيه:","o":["نفقات الحج","مواعيد الصلاة","أعطيات الجنود"],"a":2,"why":"ديوان الجند تُحدد فيه أعطيات الجنود، أي رواتبهم وما يستحقونه. أما نفقات الحج ومواعيد الصلاة فليست من عمله.","ow":["نفقات الحج ليست من اختصاص ديوان الجند.","مواعيد الصلاة ليست من اختصاص ديوان الجند.",""]},
  {"q":"ديوان الصدقات مهمته:","o":["الموازنة بين الواردات والنفقات","جمع الصدقات وتوزيعها على المستحقين","نقل الرسائل"],"a":1,"why":"ديوان الصدقات مهمته جمع الصدقات وتوزيعها على المستحقين، أما الموازنة فمن مهمة ديوان الزمام.","ow":["الموازنة بين الواردات والنفقات مهمة الزمام.","","نقل الرسائل مهمة البريد."]},
  {"q":"ديوان الزمام يتولى:","o":["نقل الرسائل","الموازنة بين الواردات والنفقات والتدقيق في الحسابات","تعيين القضاة"],"a":1,"why":"ديوان الزمام يتولى الموازنة بين الواردات والنفقات والتدقيق في الحسابات، فهو أشبه بالمراجعة المالية.","ow":["نقل الرسائل مهمة البريد.","","تعيين القضاة مهمة القضاء."]},
  {"q":"سُميت الشرطة بهذا الاسم نسبة إلى:","o":["شريط من القماش يوضع على عضد أعضائها","شرطة السيف","مدينة الشرطة"],"a":0,"why":"سُميت الشرطة بهذا الاسم نسبة إلى الشريط الذي كان يوضع على عضد أعضائها لتمييزهم عن عامة الناس.","ow":["","ليست نسبة إلى شرطة السيف.","ليست نسبة إلى مدينة."]},
  {"q":"وسّع استعمالات البريد في العصر الأموي:","o":["معاوية بن أبي سفيان","عمر بن الخطاب","أبو بكر الصديق"],"a":0,"why":"وسّع معاوية بن أبي سفيان استعمالات البريد في العصر الأموي، فصار ينقل الرسائل بسرعة بين الدولة وولاتها.","ow":["","عمر أنشأ الدواوين وليس موسع البريد.","أبو بكر لم يتسع البريد في عهده."]},
  {"q":"العبارة: قُسمت الوزارة في العصر العباسي إلى وزارة تفويض ووزارة تنفيذ.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: قُسمت الوزارة في العصر العباسي إلى وزارة تفويض ووزارة تنفيذ، بحسب صلاحيات الوزير.","ow":["","العبارة صحيحة، فهذا ما ذكره الكتاب."]},
  {"q":"العبارة: أول وزراء بني العباس أبو سلمة الخلال.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: أول وزراء بني العباس أبو سلمة الخلال، وبه بدأ نظام الوزارة في الدولة العباسية.","ow":["","العبارة صحيحة، فقد ذكر الكتاب ذلك."]},
  {"q":"العبارة: رئيس الشرطة يلقب بصاحب الشرطة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: لُقّب رئيس الشرطة بصاحب الشرطة، وكان يعاون الحاكم في حفظ الأمن وضبط المخالفين، والشرطة سُميت بالشريط الذي يميز أفرادها.","ow":["","العبارة صحيحة، فهذا لقب رئيس الشرطة."]},
  {"q":"العبارة: كان الخلفاء الراشدون يسيرون على سياسة الرسول ﷺ العسكرية.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: سار الخلفاء الراشدون على سياسة الرسول ﷺ العسكرية، فاستمر الجيش على نهجه بعد وفاته.","ow":["","العبارة صحيحة، فقد اتبعوا سياسته العسكرية."]}
];
window.BANK['so7']['so7-2-3'] = [
  {"q":"علم التفسير هو الذي:","o":["يبين معاني آيات القرآن الكريم ويوضحها","يستنبط الأحكام","يدرس النجوم"],"a":0,"why":"علم التفسير هو الذي يبين معاني آيات القرآن الكريم ويوضحها، أما استنباط الأحكام فعلم الفقه ودراسة النجوم علم الفلك.","ow":["","استنباط الأحكام يسمى الفقه.","دراسة النجوم يسمى الفلك."]},
  {"q":"من المفسرين المشهورين:","o":["الخوارزمي","عبدالله بن مسعود","ابن حوقل"],"a":1,"why":"عبد الله بن مسعود من المفسرين المشهورين من الصحابة، مع علي بن أبي طالب. أما الخوارزمي وابن حوقل فعالمان في الرياضيات والجغرافيا.","ow":["الخوارزمي عالم رياضيات.","","ابن حوقل عالم جغرافيا."]},
  {"q":"من الكتب المشهورة في الحديث:","o":["صحيح البخاري","تاريخ الطبري","صورة الأرض"],"a":0,"why":"صحيح البخاري من الكتب المشهورة في الحديث، مع صحيح مسلم. أما تاريخ الطبري ففي التاريخ وصورة الأرض في الجغرافيا.","ow":["","تاريخ الطبري كتاب في التاريخ.","صورة الأرض كتاب في الجغرافيا."]},
  {"q":"من رواة الحديث من الصحابة:","o":["أبو هريرة","ابن حيان","سيبويه"],"a":0,"why":"أبو هريرة من رواة الحديث من الصحابة، ومنهم أيضًا عائشة وأنس بن مالك. أما ابن حيان وسيبويه فليسا من رواة الحديث.","ow":["","جابر بن حيان عالم كيمياء.","سيبويه عالم نحو."]},
  {"q":"علم الفقه هو:","o":["علم الطب","علم النجوم","استنباط الأحكام الشرعية من القرآن والسنة"],"a":2,"why":"علم الفقه هو استنباط الأحكام الشرعية من القرآن والسنة، أي استخراجها وفهمها. فليس هو الطب أو النجوم.","ow":["الطب علم للأمراض وليس الفقه.","علم النجوم هو الفلك وليس الفقه.",""]},
  {"q":"أي مما يأتي من فقهاء المذاهب الأربعة؟","o":["سيبويه","الإمام مالك","ابن الهيثم"],"a":1,"why":"الإمام مالك من فقهاء المذاهب الأربعة. أما سيبويه فعالم نحو، وابن الهيثم عالم فيزياء وبصريات.","ow":["سيبويه عالم نحو وليس فقيهًا.","","ابن الهيثم عالم بصريات وليس فقيهًا."]},
  {"q":"أنشأ المسلمون علم النحو وضعوا قواعده بعد دخول غير العرب في الإسلام، ومن علمائه:","o":["الرازي","أبو الأسود الدؤلي","جابر بن حيان"],"a":1,"why":"أبو الأسود الدؤلي وضع قواعد النحو بعد دخول غير العرب في الإسلام حتى لا يخطئوا في القرآن. أما الرازي فطبيب وجابر كيميائي.","ow":["الرازي طبيب وليس من علماء النحو.","","جابر بن حيان كيميائي وليس نحويًا."]},
  {"q":"من أشهر الشعراء الذين مدحوا الرسول ﷺ:","o":["حسان بن ثابت","سيبويه","ابن حوقل"],"a":0,"why":"اشتهر حسان بن ثابت بمدح الرسول ﷺ بالشعر، وهو من أشهر شعراء الأدب. أما سيبويه فنحوي وابن حوقل جغرافي.","ow":["","سيبويه نحوي وليس شاعرًا مادحًا.","ابن حوقل جغرافي وليس شاعرًا."]},
  {"q":"علم التاريخ هو العلم الذي يدرس:","o":["الوقائع وأوقاتها","النجوم","الأعشاب"],"a":0,"why":"علم التاريخ يدرس الوقائع وأوقاتها، كما فعل الطبري في كتابه. أما النجوم فللفلك والأعشاب للصيدلة.","ow":["","دراسة النجوم هي الفلك.","دراسة الأعشاب أقرب إلى الصيدلة."]},
  {"q":"من أمثلة الجغرافيا الفلكية:","o":["جامع البيان","الأسطرلاب والمراصد","صحيح مسلم"],"a":1,"why":"من أمثلة الجغرافيا الفلكية الأسطرلاب والمراصد التي استخدمها المسلمون في رصد النجوم. أما جامع البيان وصحيح مسلم فكتابان في التفسير والحديث.","ow":["جامع البيان كتاب في التفسير.","","صحيح مسلم كتاب في الحديث."]},
  {"q":"عُرف علم الضوء باسم:","o":["الصيدلة","الجبر","البصريات"],"a":2,"why":"علم الضوء يُعرف باسم البصريات، وقد برع فيه علماء مثل البيروني وابن الهيثم. أما الصيدلة والجبر فعلمان آخران.","ow":["الصيدلة علم الأدوية.","الجبر فرع من الرياضيات.",""]},
  {"q":"برع في الكيمياء العالم الذي اشتهر بالتجربة المخبرية:","o":["جابر بن حيان","البيروني","الخوارزمي"],"a":0,"why":"جابر بن حيان برع في الكيمياء، واشتهر بالتجربة المخبرية. أما البيروني فبالفيزياء والخوارزمي بالرياضيات.","ow":["","البيروني اشتهر بالفيزياء والكثافة.","الخوارزمي اشتهر بالجبر."]},
  {"q":"من إنجازات المسلمين في الكيمياء:","o":["اختراع الصفر","بناء المراصد","تنقية المعادن والتقطير والترشيح"],"a":2,"why":"من إنجازات المسلمين في الكيمياء تنقية المعادن والتقطير والترشيح، أما اختراع الصفر فللرياضيات وبناء المراصد للفلك.","ow":["اختراع الصفر من الرياضيات.","بناء المراصد من الفلك.",""]},
  {"q":"أبو عبدالله محمد الخوارزمي اشتهر بعلم:","o":["الرياضيات (الجبر)","الطب","الأدب"],"a":0,"why":"اشتهر الخوارزمي بالرياضيات والجبر والهندسة، وهو أبو عبد الله محمد الخوارزمي. وليس طبيبًا ولا أديبًا.","ow":["","الطب علم يختص بالأمراض والعلاج، وليس هو علم الخوارزمي المشهور.","الأدب علم اللغة والشعر، وليس هو علم الخوارزمي المشهور."]},
  {"q":"ارتبط علم الفلك بالأمور الشرعية مثل:","o":["أوقات الصلاة وتحديد مواقع البلدان","تجارة الحرير","صناعة الزجاج"],"a":0,"why":"ارتبط علم الفلك بالأمور الشرعية مثل تحديد أوقات الصلاة والقبلة والمواقع، أما تجارة الحرير وصناعة الزجاج فليستا شرعيتين.","ow":["","تجارة الحرير نشاط اقتصادي.","صناعة الزجاج صناعة."]},
  {"q":"أدخل المسلمون السكر في:","o":["بناء المراصد","صناعة الأسلحة","تحلية بعض الأدوية المرة"],"a":2,"why":"أدخل المسلمون السكر في تحلية بعض الأدوية المرة، وهذا من إنجازاتهم في الصيدلة. فهو لم يدخل في المراصد أو الأسلحة.","ow":["بناء المراصد لا علاقة له بالسكر.","صناعة الأسلحة لا علاقة لها بالسكر.",""]},
  {"q":"العبارة: بدأت الترجمة في العصر الأموي وازدهرت في العصر العباسي.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: بدأت الترجمة في العصر الأموي وازدهرت في العصر العباسي، فنقلت علوم كثيرة إلى العربية.","ow":["","العبارة صحيحة، فهذا ما ذكره الكتاب."]},
  {"q":"العبارة: أنشأ المسلمون المستشفيات لمعالجة المرضى.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: اعتنى المسلمون بالطب فأنشؤوا المستشفيات لمعالجة المرضى، وصنعوا أدوات جراحية.","ow":["","العبارة صحيحة، فقد أنشؤوا المستشفيات."]},
  {"q":"العبارة: البيروني اشتهر بتأليف تاريخ الطبري.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: تاريخ الطبري ألّفه الطبري، أما البيروني فاشتهر باكتشاف الكثافة والفيزياء.","ow":["الصحيح أن الطبري ألّف تاريخه، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: اخترع المسلمون الصفر واستعملوا نظام الترقيم.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: اخترع المسلمون الصفر واستعملوا نظام الترقيم، وهو من أهم منجزاتهم في الرياضيات.","ow":["","العبارة صحيحة، فقد ذكر الكتاب ذلك."]}
];
window.BANK['so7']['so7-2-4'] = [
  {"q":"اعتنت الحضارة الإسلامية بعامل:","o":["الجمال","الحرب فقط","التجارة فقط"],"a":0,"why":"اعتنت الحضارة الإسلامية بعامل الجمال في البناء والفنون، فلم تقتصر على الحرب والتجارة.","ow":["","الحرب وحدها لا تمثل اهتمامات الحضارة.","التجارة وحدها لا تمثل اهتمامات الحضارة."]},
  {"q":"من الفنون التي جمعت بينها الحضارة الإسلامية:","o":["الغناء فقط","التمثيل","البناء والنحت والرسم والخط والزخرفة"],"a":2,"why":"جمعت الحضارة الإسلامية بين فن البناء والنحت والرسم والخط والزخرفة، فهي فنون متكاملة، لا الغناء وحده ولا التمثيل.","ow":["الغناء وحده لا يمثل فنونها.","التمثيل ليس من الفنون المذكورة في الدرس.",""]},
  {"q":"كان الفن الإسلامي مرتبطًا بـ:","o":["اللهو","الحرب","الدين"],"a":2,"why":"كان الفن الإسلامي مرتبطًا بالدين، فنُقشت الآيات القرآنية على الأواني والمباني. ولم يرتبط باللهو أو الحرب.","ow":["اللهو ليس أساس الفنون الإسلامية.","الحرب لم تكن أساس الفنون الإسلامية.",""]},
  {"q":"يقع الجامع الأموي في مدينة:","o":["القدس","دمشق","القاهرة","قرطبة"],"a":1,"why":"يقع الجامع الأموي في مدينة دمشق، عاصمة الدولة الأموية، وهو من أشهر المساجد في العمارة الإسلامية. أما قرطبة ففيها مسجد آخر.","ow":["القدس فيها المسجد الأقصى وقبة الصخرة.","","القاهرة فيها قلعة صلاح الدين.","قرطبة فيها مسجد قرطبة."]},
  {"q":"يقع مسجد قرطبة في:","o":["العراق","فلسطين","الأندلس"],"a":2,"why":"يقع مسجد قرطبة في الأندلس، وهو من أشهر مساجد العصر الإسلامي في أوروبا. وليس في العراق أو فلسطين.","ow":["العراق ليس موقع مسجد قرطبة.","فلسطين فيها قبة الصخرة والأقصى.",""]},
  {"q":"يقع المسجد الأقصى في:","o":["القدس","القيروان","دمشق"],"a":0,"why":"يقع المسجد الأقصى في القدس (بيت المقدس) في فلسطين، أما القيروان ففيها مسجد عقبة ودمشق فيها الجامع الأموي.","ow":["","القيروان فيها مسجد عقبة بن نافع.","دمشق فيها الجامع الأموي."]},
  {"q":"مسجد عقبة بن نافع يقع في مدينة:","o":["قرطبة","مكة","القيروان"],"a":2,"why":"مسجد عقبة بن نافع في مدينة القيروان بتونس، أما قرطبة ففيها مسجد قرطبة ومكة فيها المسجد الحرام.","ow":["قرطبة فيها مسجد قرطبة.","مكة فيها المسجد الحرام.",""]},
  {"q":"لم تظهر العناية ببناء القصور في عصر:","o":["الدولة العباسية","الدولة الأموية","الرسول ﷺ والخلفاء الراشدين"],"a":2,"why":"لم تظهر العناية بالقصور في عصر الرسول ﷺ والخلفاء الراشدين لأنهم تميزوا بالبساطة والزهد، وظهرت في الأموية والعباسية.","ow":["الدولة العباسية اعتنت بالقصور.","الدولة الأموية اعتنت بالقصور.",""]},
  {"q":"اعتنى بإنشاء القصور وزخرفتها خلفاء:","o":["الدولة الأموية والعباسية","الصحابة","الخلفاء الراشدين"],"a":0,"why":"اعتنى خلفاء الدولتين الأموية والعباسية بإنشاء القصور وزخرفتها، أما الصحابة والخلفاء الراشدون فكانوا بسطاء.","ow":["","الصحابة تميزوا بالبساطة والزهد.","الخلفاء الراشدون لم يعتنوا بالقصور."]},
  {"q":"قصر عمرة بُني في عصر الدولة:","o":["الراشدة","الأموية","العباسية"],"a":1,"why":"بُني قصر عمرة في الصحراء الأردنية في العصر الأموي، وهو مثال على عناية الأمويين بالقصور.","ow":["الدولة الراشدة تميزت بالبساطة.","","الدولة العباسية بنت قصورًا أخرى."]},
  {"q":"بُني قصر الحمراء في عصر مملكة:","o":["دمشق","غرناطة","بغداد"],"a":1,"why":"بُني قصر الحمراء في عصر مملكة غرناطة في الأندلس، في القرن السابع الهجري، وهو من أجمل القصور الإسلامية.","ow":["دمشق عاصمة الأمويين.","","بغداد عاصمة العباسيين."]},
  {"q":"بنى المسلمون المدن في الأماكن التي فتحوها لتكون:","o":["عواصم أو لأغراض عسكرية أو اقتصادية أو دينية","سجونًا","مزارع فقط"],"a":0,"why":"بنى المسلمون المدن في الأماكن التي فتحوها لتكون عواصم أو لأغراض عسكرية أو اقتصادية أو دينية، لا سجونًا ولا مزارع فقط.","ow":["","لم تبنَ المدن لتكون سجونًا.","لم تبنَ المدن لتكون مزارع فقط."]},
  {"q":"من المدن الإسلامية:","o":["الأهرام","أكاد","القاهرة"],"a":2,"why":"القاهرة من المدن الإسلامية المهمة، مع البصرة والكوفة وبغداد والقيروان، أما الأهرام فآثار فرعونية وأكاد مدينة قديمة.","ow":["الأهرام آثار فرعونية.","أكاد مدينة قديمة قبل الإسلام.",""]},
  {"q":"الحصون والقلاع هي:","o":["مدن صغيرة محصنة لحماية حدود الدولة","أسواق كبيرة","قصور للترفيه"],"a":0,"why":"الحصون والقلاع مدن صغيرة محصنة لحماية حدود الدولة، وفيها أماكن إقامة ومرافق ومياه وأسواق، فليست أسواقًا كبيرة ولا قصورًا للترفيه.","ow":["","ليست أسواقًا كبيرة، بل مدن محصنة.","ليست قصورًا للترفيه، بل للدفاع."]},
  {"q":"قلعة عكا وقلعة حلب من:","o":["القصور","القلاع الإسلامية","المساجد"],"a":1,"why":"قلعة عكا وقلعة حلب من القلاع الإسلامية لحماية الحدود والمدن، فليستا قصرين للترفيه ولا مسجدين للعبادة، وإنما حصنان للدفاع.","ow":["القصور مثل الحمراء وعمرة.","","المساجد مثل الأموي وقرطبة."]},
  {"q":"قلعة الربض تقع في:","o":["حمص","القاهرة","عجلون"],"a":2,"why":"قلعة الربض تقع في عجلون بالأردن، أما قلعة الحصن ففي حمص وقلعة صلاح الدين في القاهرة.","ow":["حمص فيها قلعة الحصن.","القاهرة فيها قلعة صلاح الدين.",""]},
  {"q":"العبارة: قبة الصخرة مسجد يقع في فلسطين.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: قبة الصخرة مسجد يقع في فلسطين، في القدس، وهي من أشهر العمارة الإسلامية.","ow":["","العبارة صحيحة، فهي في فلسطين."]},
  {"q":"العبارة: قلعة الحصن تقع في حمص.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: قلعة الحصن تقع في حمص بسوريا، وهي من القلاع الإسلامية لحماية الحدود.","ow":["","العبارة صحيحة، فالقلعة في حمص."]},
  {"q":"العبارة: بُني قصر الحمراء في العصر العباسي.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: بُني قصر الحمراء في عصر مملكة غرناطة في الأندلس، وليس في العصر العباسي.","ow":["الصحيح أنه من عصر غرناطة، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: تميز عصر الرسول ﷺ والخلفاء الراشدين بالبساطة والزهد في البناء.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: تميز عصر الرسول ﷺ والخلفاء الراشدين بالبساطة والزهد، ولم تظهر العناية بالقصور فيه.","ow":["","العبارة صحيحة، فقد كان عصر بساطة."]}
];
window.BANK['so7']['so7-2-5'] = [
  {"q":"مزجت الحضارة الإسلامية بين:","o":["العقل والروح","الحرب والسلام فقط","الماضي فقط"],"a":0,"why":"مزجت الحضارة الإسلامية بين العقل والروح، فاهتمت بالعلم والدين معًا ولم تغفل الجوانب الاقتصادية، وهذا ميزها عن غيرها.","ow":["","لم تقتصر على الحرب والسلام فقط.","لم تقتصر على الماضي فقط."]},
  {"q":"من الجوانب الاقتصادية في الحضارة الإسلامية:","o":["الحروب فقط","الشعر فقط","الزراعة والصناعة والتجارة"],"a":2,"why":"من الجوانب الاقتصادية في الحضارة الإسلامية الزراعة والصناعة والتجارة، فلا تقتصر على الحروب أو الشعر.","ow":["الحروب ليست جانبًا اقتصاديًا فقط.","الشعر ليس من الجوانب الاقتصادية.",""]},
  {"q":"الزراعة هي المصدر الأول لـ:","o":["غذاء الإنسان","السلاح","الأدوية"],"a":0,"why":"الزراعة هي المصدر الأول لغذاء الإنسان، ولذلك اهتم بها المسلمون بالري والتسميد. أما السلاح والأدوية فمن الصناعات.","ow":["","السلاح من الصناعات المعدنية.","الأدوية من الصناعات الكيميائية."]},
  {"q":"أي مما يأتي من مظاهر العناية بالري؟","o":["ترك الأرض","بناء السدود وإقامة الجسور والقناطر وحفر القنوات","قطع الأشجار"],"a":1,"why":"من مظاهر العناية بالري بناء السدود وإقامة الجسور والقناطر وحفر القنوات مع تجفيف المستنقعات. وترك الأرض وقطع الأشجار ضد العناية.","ow":["ترك الأرض ضد العناية بالزراعة.","","قطع الأشجار يضر بالزراعة ولا يخدم الري."]},
  {"q":"العناية بالأرض تكون بتسميدها بالسماد:","o":["الصالح لكل نوع من النباتات","الواحد لجميع النباتات","الملوث"],"a":0,"why":"العناية بالأرض تكون بتسميدها بالسماد الصالح لكل نوع من النباتات، فلكل نبات احتياجه. ولا يصلح سماد واحد لكل النباتات.","ow":["","سماد واحد لجميع النباتات لا يناسب احتياج كل نبات.","السماد الملوث يضر الأرض."]},
  {"q":"تعددت أنواع المزروعات بسبب اتساع المساحة وتنوع:","o":["مناخ الأقاليم","اللغات","الحدود"],"a":0,"why":"تعددت أنواع المزروعات لاتساع المساحة وتنوع مناخ الأقاليم الإسلامية، فنمت الحبوب والفواكه والقطن وغيرها. أما اللغات والحدود فلا علاقة لها.","ow":["","اللغات لا علاقة لها بتنوع المزروعات.","الحدود لا علاقة لها بتنوع المزروعات."]},
  {"q":"من المزروعات التي ذكرها الكتاب:","o":["القطن والزيتون والعنب والنخيل","الشاي فقط","الأرز فقط"],"a":0,"why":"ذكر الكتاب من المزروعات القطن والزيتون والعنب والنخيل، إلى جانب الحبوب والخضراوات والفواكه. فلم تقتصر على الشاي أو الأرز.","ow":["","الشاي وحده لا يمثل المزروعات.","الأرز وحده لا يمثل المزروعات."]},
  {"q":"صناعة الأسلحة والأواني من الصناعات:","o":["المعدنية","الكيميائية","الزجاجية"],"a":0,"why":"الأسلحة والأواني من الصناعات المعدنية، مثل المحراث والفأس. أما الأدوية والعطور فكيميائية.","ow":["","الكيميائية للأدوية والعطور والصابون.","الزجاجية للزجاج والأواني المنزلية."]},
  {"q":"صناعة الصابون من الصناعات:","o":["المعدنية","المنسوجات","الكيميائية"],"a":2,"why":"الصابون من الصناعات الكيميائية، مثل الأدوية والعطور. أما المعدنية فالأسلحة والأواني والمنسوجات للحرير والصوف.","ow":["المعدنية للأسلحة والأواني.","المنسوجات للحرير والصوف والكتان.",""]},
  {"q":"صناعة الحرير والصوف والكتان تسمى صناعة:","o":["الزجاج","المعادن","المنسوجات"],"a":2,"why":"صناعة الحرير والصوف والكتان تسمى صناعة المنسوجات، وهي من أشهر الصناعات. أما الزجاج والمعادن فصناعتان أخريان.","ow":["الزجاج صناعة أخرى.","المعادن صناعة أخرى.",""]},
  {"q":"صناعة الزجاج والأواني المنزلية من الصناعات:","o":["الكيميائية","الزجاجية والخزفية","المعدنية"],"a":1,"why":"صناعة الزجاج والأواني المنزلية من الصناعات الزجاجية والخزفية، أما الكيميائية فللأدوية والعطور والمعدنية للأسلحة.","ow":["الكيميائية للأدوية والعطور.","","المعدنية للأسلحة والأواني المعدنية."]},
  {"q":"كان للعرب معرفة بالتجارة قبل الإسلام بسبب:","o":["كثرة الأنهار","الصناعات الثقيلة","موقع شبه الجزيرة العربية المتميز"],"a":2,"why":"كان للعرب معرفة بالتجارة قبل الإسلام بسبب موقع شبه الجزيرة العربية المتميز بين القارات. أما الأنهار والصناعات الثقيلة فلم تكن لها.","ow":["لم تكن الأنهار كثيرة في الجزيرة العربية.","لم تكن الصناعات الثقيلة كثيرة آنذاك.",""]},
  {"q":"أي مما يأتي من عوامل ازدهار التجارة؟","o":["إغلاق الأسواق","الحروب الأهلية","استقرار الأمن في البلاد"],"a":2,"why":"استقرار الأمن في البلاد من عوامل ازدهار التجارة، لأن التاجر لا يخاف على بضاعته. أما إغلاق الأسواق والحروب الأهلية فتعطلها.","ow":["إغلاق الأسواق يعطل التجارة.","الحروب الأهلية تضعف التجارة.",""]},
  {"q":"من عوامل ازدهار التجارة أيضًا:","o":["تنوع المحصولات الزراعية","قلة الصناعات","ضعف الأمن"],"a":0,"why":"تنوع المحصولات الزراعية من عوامل ازدهار التجارة، لأنه يوفر بضاعة كثيرة للبيع. أما قلة الصناعات وضعف الأمن فتضعفانها.","ow":["","قلة الصناعات تقلل البضائع.","ضعف الأمن يضر بالتجارة."]},
  {"q":"أصبح للتجار المسلمين صلات مع غيرهم فأسهموا في:","o":["نشر الإسلام","نشر الفوضى","منع التجارة"],"a":0,"why":"أصبح للتجار المسلمين صلات مع غيرهم، فأسهموا في نشر الإسلام بحسن معاملتهم وأمانتهم. ولم ينشروا الفوضى أو يمنعوا التجارة.","ow":["","نشر الفوضى ليس نتيجة عملهم.","منع التجارة ضد ما فعلوه."]},
  {"q":"العبارة: تعد الزراعة مصدرًا أول لغذاء الإنسان.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: الزراعة مصدر أول لغذاء الإنسان، ولهذا اعتنى بها المسلمون بالري والتسميد.","ow":["","العبارة صحيحة، فالزراعة مصدر الغذاء الأول."]},
  {"q":"العبارة: المحراث والفأس من الصناعات الكيميائية.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: المحراث والفأس من الصناعات المعدنية، أما الكيميائية فللأدوية والعطور والصابون.","ow":["الصحيح أنهما من الصناعات المعدنية، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: أسهم التجار المسلمون في نشر الإسلام بأمانتهم وتسامحهم.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: أسهم التجار المسلمون في نشر الإسلام بأمانتهم وتسامحهم مع تمسكهم بأحكام الدين.","ow":["","العبارة صحيحة، فقد كانت أخلاقهم دعوة للإسلام."]},
  {"q":"العبارة: لم تهتم الحضارة الإسلامية بالجوانب الاقتصادية.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: الحضارة الإسلامية لم تغفل الجوانب الاقتصادية، بل اهتمت بالزراعة والصناعة والتجارة.","ow":["الصحيح أنها اهتمت بالجوانب الاقتصادية، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: صناعة العطور والأدوية من الصناعات الكيميائية.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: صناعة العطور والأدوية والصابون من الصناعات الكيميائية، أما الأسلحة والأواني فمن الصناعات المعدنية.","ow":["","العبارة صحيحة، فهي من الصناعات الكيميائية."]}
];
window.BANK['so7']['so7-3-1'] = [
  {"q":"يقصد بالتخطيط:","o":["الإعداد المنظم لتحديد المهام والأعمال المستقبلية ومواعيد القيام بها","تأجيل الأعمال","النوم الطويل"],"a":0,"why":"التخطيط هو الإعداد المنظم لتحديد المهام والأعمال المستقبلية ومواعيد القيام بها. فليس هو تأجيل الأعمال ولا النوم الطويل.","ow":["","تأجيل الأعمال ضد التخطيط.","النوم الطويل ليس تعريف التخطيط."]},
  {"q":"التخطيط يجيب عن الأسئلة:","o":["ماذا؟ ومتى؟ وكيف؟","من أين؟ فقط","لماذا؟ فقط"],"a":0,"why":"التخطيط يجيب عن الأسئلة: ماذا؟ ومتى؟ وكيف؟ أي نعرف المهمة التي نريد إنجازها وموعدها وطريقة إنجازها، فيصبح العمل منظمًا.","ow":["","من أين؟ سؤال واحد لا يكفي.","لماذا؟ سؤال واحد لا يكفي."]},
  {"q":"أي مما يأتي من أهداف التخطيط؟","o":["الفشل","النجاح والتفوق","الإهمال"],"a":1,"why":"من أهداف التخطيط النجاح والتفوق، فهو الهدف الأول للتخطيط. أما الفشل والإهمال فنتيجة غيابه.","ow":["الفشل نتيجة غياب التخطيط.","","الإهمال ضد التخطيط."]},
  {"q":"يساعدك التخطيط على:","o":["ضياع الوقت","استغلال الوقت وتحقيق المهام الدراسية","ترك الدراسة"],"a":1,"why":"يساعدك التخطيط على استغلال الوقت وتحقيق المهام الدراسية، ولا يؤدي إلى ضياع الوقت أو ترك الدراسة.","ow":["ضياع الوقت ضد فائدة التخطيط.","","ترك الدراسة ليس من فوائد التخطيط."]},
  {"q":"يساعد التخطيط على اتخاذ:","o":["قرارات عشوائية","قرارات صائبة","قرارات متأخرة"],"a":1,"why":"يساعد التخطيط على اتخاذ قرارات صائبة والنجاح في الحياة، لأنك تفكر قبل أن تفعل. أما العشوائية والتأخر فنتيجة غيابه.","ow":["القرارات العشوائية نتيجة غياب التخطيط.","","القرارات المتأخرة ليست هدف التخطيط."]},
  {"q":"من أهداف التخطيط بناء الشخصية:","o":["المتكاسلة","الوطنية الناجحة والحضارية","المترددة"],"a":1,"why":"من أهداف التخطيط بناء الشخصية الوطنية الناجحة والحضارية، لا المتكاسلة ولا المترددة.","ow":["المتكاسلة ضد التخطيط.","","المترددة ليست من أهداف التخطيط."]},
  {"q":"يساعد التخطيط على مواكبة طموحات:","o":["رؤية 1990","رؤية 2010","رؤية وطننا 2030"],"a":2,"why":"يساعد التخطيط على مواكبة طموحات رؤية وطننا 2030، وهي التي تحث على الإنجاز والإتقان.","ow":["رؤية 1990 ليست رؤية المملكة.","رؤية 2010 ليست الرؤية المذكورة.",""]},
  {"q":"تحث رؤية 2030 على:","o":["التأجيل","السهر","الإنجاز والإتقان"],"a":2,"why":"تحث رؤية 2030 على الإنجاز والإتقان، ولا تحث على التأجيل أو السهر. ولهذا يساعدنا التخطيط على مواكبة طموحات هذه الرؤية.","ow":["التأجيل ضد الإنجاز.","السهر ليس هدفها.",""]},
  {"q":"في جانب الصحة يهدف التخطيط إلى:","o":["السهر الطويل","انتظام النوم ومواعيد الوجبات","ترك الوجبات"],"a":1,"why":"في جانب الصحة يهدف التخطيط إلى انتظام النوم ومواعيد الوجبات، فلا سهر طويل ولا ترك الوجبات.","ow":["السهر الطويل يضر بالصحة.","","ترك الوجبات يضر بالصحة."]},
  {"q":"في جدول طالب نموذجي، يخصص وقت الغداء مع الأسرة في الساعة:","o":["5:30 مساءً","3:00 مساءً","9:30 مساءً"],"a":1,"why":"في الجدول النموذجي كان الغداء مع الأسرة في الساعة 3:00 مساءً، ثم صلاة العصر 3:30، ثم مذاكرة الرياضيات 4:00.","ow":["5:30 مساءً وقت حل واجب العلوم.","","9:30 مساءً وقت الذهاب إلى النوم."]},
  {"q":"يزداد الاهتمام بالتخطيط للنجاح الدراسي في المرحلة:","o":["الروضة","المتوسطة","الجامعية فقط"],"a":1,"why":"يزداد الاهتمام بالتخطيط للنجاح الدراسي في المرحلة المتوسطة، حين يبدأ الطلبة الحرص على الاستفادة من وقتهم.","ow":["الروضة مرحلة مبكرة جدًا لهذا الاهتمام.","","الجامعية فقط ليست المقصودة."]},
  {"q":"الإنجازات لم تتحقق بدون إيمان وعمل:","o":["المواطن السعودي","المقيم الأجنبي","السائح"],"a":0,"why":"قال سمو ولي العهد الأمير محمد بن سلمان إن الإنجازات لم تتحقق بدون إيمان وعمل المواطن السعودي.","ow":["","المقيم الأجنبي ليس المقصود في القول.","السائح ليس المقصود في القول."]},
  {"q":"المواطن الفاعل يعتمد على:","o":["حسن التخطيط","الحظ","التأجيل"],"a":0,"why":"المواطن الفاعل يعتمد على حسن التخطيط، فلا يعتمد على الحظ ولا التأجيل. وبذلك ترتبط الإنجازات به.","ow":["","الحظ ليس أساس نجاح المواطن الفاعل.","التأجيل ضد الفاعلية."]},
  {"q":"يساعد التخطيط على معرفة ما يجب فعله و:","o":["من يؤديه عنا","متى نؤديه","ما لا نحبه"],"a":1,"why":"يساعد التخطيط على معرفة ما يجب فعله ومتى نؤديه، أي ترتيب المهام بحسب مواعيدها، فلا يضيع الوقت ولا تتأخر الأعمال.","ow":["من يؤديه عنا ليس من فوائد التخطيط.","","ما لا نحبه ليس هدف التخطيط."]},
  {"q":"من فوائد التخطيط تحديد الأهداف و:","o":["إلغاء الأهداف","رسم طرائق مناسبة لتحقيقها","تأجيلها"],"a":1,"why":"من فوائد التخطيط تحديد الأهداف ورسم طرائق مناسبة لتحقيقها، فلا إلغاء للأهداف ولا تأجيل لها.","ow":["إلغاء الأهداف ضد التخطيط.","","تأجيل الأهداف ضد التخطيط."]},
  {"q":"العبارة: التخطيط إعداد منظم للمهام ومواعيدها وكيفية إنجازها.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: التخطيط إعداد منظم للمهام ومواعيدها وكيفية إنجازها، وهذا هو تعريفه في الكتاب.","ow":["","العبارة صحيحة، فهذا هو تعريف التخطيط."]},
  {"q":"العبارة: لا نحتاج إلى التخطيط لتحقيق أهدافنا.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: نحتاج إلى التخطيط لتحقيق أهدافنا، فمن غير خطة تضيع الجهود والأوقات.","ow":["الصحيح أن التخطيط ضروري، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: من أهداف التخطيط انتظام النوم ومواعيد الوجبات.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: من أهداف التخطيط انتظام النوم ومواعيد الوجبات، وهذا من جانب الصحة.","ow":["","العبارة صحيحة، فهذا من أهداف التخطيط الصحي."]},
  {"q":"العبارة: التخطيط يزيد الاهتمام بالنجاح الدراسي في المرحلة المتوسطة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: يزيد الاهتمام بالتخطيط للنجاح الدراسي في المرحلة المتوسطة، فالطلبة يبدؤون الحرص على وقتهم.","ow":["","العبارة صحيحة، فهذا ما ذكره الكتاب."]},
  {"q":"العبارة: السهر وترك الوجبات من أهداف التخطيط الصحي.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: السهر وترك الوجبات يضران بالصحة، والمقصود بالتخطيط انتظام النوم ومواعيد الوجبات.","ow":["الصحيح أن الهدف انتظام النوم والوجبات، فالعبارة غير صحيحة.",""]}
];
window.BANK['so7']['so7-3-2'] = [
  {"q":"التخطيط يساعد على:","o":["ترك الأعمال","إضاعة الوقت","تنظيم الوقت واختيار الأسلوب المناسب للدراسة"],"a":2,"why":"التخطيط يساعد على تنظيم الوقت واختيار الأسلوب المناسب للدراسة، فلا يؤدي إلى ترك الأعمال أو إضاعة الوقت.","ow":["ترك الأعمال ضد التخطيط.","إضاعة الوقت ضد التخطيط.",""]},
  {"q":"من وسائل تنظيم الوقت:","o":["التطبيقات الإلكترونية","النوم","تأجيل الأعمال"],"a":0,"why":"من وسائل تنظيم الوقت التطبيقات الإلكترونية، أو القلم والورقة وعمل الجداول. فالمهم نظام مناسب لإتمام الدراسة في وقتها.","ow":["","النوم لا ينظم الوقت.","تأجيل الأعمال ضد التنظيم."]},
  {"q":"الخطوة الأولى في تنظيم الوقت:","o":["تحديد الزمن","حصر الأعمال اليومية","تصميم الجدول"],"a":1,"why":"الخطوة الأولى في تنظيم الوقت حصر الأعمال اليومية، أي كتابة كل ما علينا فعله، ثم تحديد الزمن اللازم لها، ثم تصميم جدول بها.","ow":["تحديد الزمن هو الخطوة الثانية.","","تصميم الجدول هو الخطوة الثالثة."]},
  {"q":"الخطوة الثالثة في تنظيم الوقت:","o":["حصر الأعمال","النوم","تصميم جدول للأعمال"],"a":2,"why":"الخطوة الثالثة تصميم جدول للأعمال التي جرى حصرها، بعد حصرها وتحديد الزمن اللازم لها.","ow":["حصر الأعمال هو الخطوة الأولى.","النوم ليس من خطوات التنظيم.",""]},
  {"q":"يتوازن الطالب في وقته بين:","o":["الدراسة والأسرة والعبادات والراحة والرياضة والهوايات","النوم فقط","اللعب فقط"],"a":0,"why":"يتوازن الطالب في وقته بين الدراسة والأسرة والعبادات والراحة والرياضة والهوايات، فلا يهمل جانبًا لحساب جانب.","ow":["","النوم وحده لا يحقق التوازن.","اللعب وحده يهمل الدراسة."]},
  {"q":"أي مما يأتي من فوائد تنظيم الوقت؟","o":["ضياع الوقت","الحد من التوتر والقلق","زيادة القلق"],"a":1,"why":"من فوائد تنظيم الوقت الحد من التوتر والقلق مع الاستفادة الكاملة من الوقت، أما ضياع الوقت وزيادة القلق فنتيجة غياب التنظيم.","ow":["ضياع الوقت ضد التنظيم.","","زيادة القلق نتيجة غياب التنظيم."]},
  {"q":"من فوائد تنظيم الوقت أيضًا:","o":["تأخير الواجبات","ترك المذاكرة","أداء الأعمال في الوقت المحدد لها"],"a":2,"why":"من فوائد تنظيم الوقت أداء الأعمال في الوقت المحدد لها، فلا تتأخر الواجبات ولا تُترك المذاكرة.","ow":["تأخير الواجبات ضد التنظيم.","ترك المذاكرة ضد التنظيم.",""]},
  {"q":"عند حصر الأعمال نكتب جميع الأعمال في:","o":["ورقة كل عمل","الذاكرة فقط","قائمة واحدة"],"a":2,"why":"عند حصر الأعمال نكتب جميعها في قائمة واحدة، حتى لا ننسى منها شيئًا. لا نعتمد على الذاكرة وحدها.","ow":["ورقة لكل عمل تشتت القائمة.","الذاكرة وحدها قد تنسى.",""]},
  {"q":"نرتب الأعمال في القائمة وفق:","o":["الحروف الأبجدية","الصعوبة فقط","الأولوية"],"a":2,"why":"نرتب الأعمال في القائمة وفق الأولوية، فنبدأ بالأهم والأعجل. لا نرتبها بالحروف الأبجدية فقط.","ow":["الحروف الأبجدية لا تدل على أهمية العمل.","الصعوبة وحدها ليست معيار الترتيب.",""]},
  {"q":"عند تحديد الوقت لكل عمل نترك وقتًا:","o":["للنوم فقط","لما يطرأ","للعب فقط"],"a":1,"why":"عند تحديد الوقت لكل عمل نترك وقتًا لما يطرأ، أي للظروف المفاجئة، حتى لا يختل الجدول.","ow":["وقت الطوارئ ليس للنوم فقط، بل للأمور المفاجئة المختلفة.","","وقت الطوارئ ليس للعب فقط، بل للأمور المفاجئة المختلفة."]},
  {"q":"الاستراحة المقترحة تكون كل:","o":["50 أو 60 دقيقة من الدراسة","3 ساعات","5 دقائق"],"a":0,"why":"الاستراحة المقترحة كل 50 أو 60 دقيقة من الدراسة، فهي تعين على التركيز. أما 3 ساعات فطويلة و5 دقائق قصيرة.","ow":["","3 ساعات مدة طويلة بين الاستراحات.","5 دقائق لا تكفي للراحة."]},
  {"q":"كم تبلغ مدة الاستراحة المقترحة؟","o":["30 ثانية","ساعة كاملة","10 إلى 15 دقيقة"],"a":2,"why":"مدة الاستراحة المقترحة من 10 إلى 15 دقيقة، فلا تكون ثواني قليلة لا تكفي للراحة ولا ساعة كاملة تضيع الوقت.","ow":["30 ثانية لا تكفي للراحة.","ساعة كاملة تضيع الوقت.",""]},
  {"q":"يعتمد النجاح على معرفة:","o":["كثرة النوم","قيمة الوقت وأهميته","الحظ"],"a":1,"why":"يعتمد النجاح على معرفة قيمة الوقت وأهميته. أما كثرة النوم والحظ فلا يصنعان النجاح.","ow":["كثرة النوم تضيع الوقت.","","الحظ لا يغني عن العمل والتخطيط."]},
  {"q":"قال النبي ﷺ: «إن الله تعالى يحب إذا عمل أحدكم عملًا أن ...»:","o":["يؤجله","يتركه","يتقنه"],"a":2,"why":"قال النبي ﷺ: «إن الله تعالى يحب إذا عمل أحدكم عملًا أن يتقنه»، أي يؤديه بإحكام وجودة.","ow":["التأجيل ليس مما يحبه الله.","الترك ليس مما يحبه الله.",""]},
  {"q":"المثابرة والالتزام بالخطة تؤدي إلى:","o":["القلق","الفشل","نتيجة ممتازة"],"a":2,"why":"المثابرة والالتزام بالخطة تؤديان إلى نتيجة ممتازة، أما القلق والفشل فنتيجة الإهمال.","ow":["القلق ليس نتيجة المثابرة.","الفشل نتيجة الإهمال وليس المثابرة.",""]},
  {"q":"العبارة: تحديد الزمن لإنجاز الأعمال هو الخطوة الثانية.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: تحديد الزمن لإنجاز الأعمال هو الخطوة الثانية بعد حصر الأعمال وقبل تصميم الجدول.","ow":["","العبارة صحيحة، فهذا ترتيب الخطوات."]},
  {"q":"العبارة: وضع الأعمال المهمة وغير المهمة معًا دون ترتيب في الخطة أمر مفيد.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: يجب ترتيب الأعمال وفق الأولوية، ولا يفيد وضع المهم وغير المهم معًا دون ترتيب.","ow":["الصحيح أن الترتيب بالأولوية ضروري، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: الاستراحة تعين على التركيز.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: الاستراحة من 10 إلى 15 دقيقة كل 50 أو 60 دقيقة من الدراسة تعين على التركيز وتجدد نشاط الطالب.","ow":["","العبارة صحيحة، فالراحة تعيد النشاط."]},
  {"q":"العبارة: تنظيم الوقت يحقق التوازن بين الأعمال المطلوبة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: تنظيم الوقت يحقق التوازن بين الأعمال المطلوبة: الدراسة والأسرة والعبادة والراحة.","ow":["","العبارة صحيحة، فهذه فائدته."]},
  {"q":"العبارة: لا علاقة بين التخطيط وتنظيم الوقت.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: التخطيط يساعد على تنظيم الوقت واختيار الأسلوب المناسب للدراسة، فبينهما علاقة وثيقة ولا ينفصل أحدهما عن الآخر.","ow":["الصحيح أن بينهما علاقة، فالعبارة غير صحيحة.",""]}
];
window.BANK['so7']['so7-4-1'] = [
  {"q":"كانت السيادة في مكة المكرمة بعد إسماعيل عليه السلام لقبيلة:","o":["ثقيف","جرهم","قريش","عبس"],"a":1,"why":"كانت السيادة في مكة بعد إسماعيل عليه السلام لقبيلة جرهم، ثم انتقلت بعد ذلك إلى قريش.","ow":["ثقيف قبيلة الطائف.","","قريش جاءت بعد جرهم.","عبس قبيلة في نجد."]},
  {"q":"قبيلة جرهم قبيلة:","o":["رومية","قحطانية","قرشية"],"a":1,"why":"قبيلة جرهم قبيلة قحطانية، أي تنتسب إلى قحطان، وقد تزوج إسماعيل عليه السلام منها، وكانت لها السيادة في مكة قبل قريش.","ow":["جرهم قبيلة عربية قحطانية وليست قبيلة رومية.","","لم تكن قرشية، فقريش جاءت بعدها."]},
  {"q":"الذي رفع مكانة قريش ومكّنها من زعامة مكة:","o":["عبد المطلب","قصي بن كلاب","هاشم بن عبد مناف"],"a":1,"why":"الذي رفع مكانة قريش ومكّنها من زعامة مكة هو قصي بن كلاب، وقد بنى دار الندوة للتشاور. أما هاشم فاشتهر برحلتي الشتاء والصيف.","ow":["عبد المطلب جاء بعد قصي بزمن.","","هاشم استحدث رحلتي الشتاء والصيف."]},
  {"q":"الذي استحدث رحلتي الشتاء والصيف:","o":["قصي","أبو طالب","هاشم بن عبد مناف"],"a":2,"why":"هاشم بن عبد مناف هو الذي استحدث رحلتي الشتاء والصيف لقريش، فتوسعت تجارتها. أما قصي فبنى دار الندوة وعبد المطلب حفر زمزم.","ow":["قصي بنى دار الندوة.","أبو طالب عم النبي ﷺ وليس صاحب الرحلتين.",""]},
  {"q":"في عهد عبد المطلب حدث غزو:","o":["الفرس","أبرهة ومولد النبي ﷺ","الروم"],"a":1,"why":"في عهد عبد المطلب حدث غزو أبرهة لمكة وولد النبي ﷺ، ولذلك سُمّي ذلك العام عام الفيل. ولم يكن الغزو من الفرس أو الروم.","ow":["الفرس لم يغزوا مكة في عهد عبد المطلب.","","الروم لم يغزوا مكة في عهده."]},
  {"q":"الأوس والخزرج قبيلتان في:","o":["الطائف","يثرب","مكة"],"a":1,"why":"كانت قبيلتا الأوس والخزرج تسكنان يثرب، وهي المدينة المنورة، أما مكة فسكنتها قريش والطائف ثقيف.","ow":["الطائف سكنتها ثقيف.","","مكة سكنتها قريش."]},
  {"q":"عبس وذبيان فرعان من قبيلة:","o":["الأوس","قريش","غطفان"],"a":2,"why":"عبس وذبيان فرعان من قبيلة غطفان، وبينهما اشتعلت حرب داحس والغبراء نحو أربعين سنة.","ow":["الأوس قبيلة في يثرب.","قريش قبيلة مكة.",""]},
  {"q":"الحنيفية هي ملة:","o":["عيسى","موسى","إبراهيم عليه السلام"],"a":2,"why":"الحنيفية هي ملة إبراهيم عليه السلام، وأتباعها الحنفاء، أما عيسى وموسى عليهما السلام فلكل منهما شريعة.","ow":["عيسى عليه السلام جاءت بعده النصرانية.","موسى عليه السلام جاءت بعده اليهودية.",""]},
  {"q":"انحرف بعض العرب فعبدوا:","o":["الأصنام والأجرام والنار","الله وحده","الملائكة فقط"],"a":0,"why":"انحرف بعض العرب فعبدوا الأصنام والأجرام والنار، وانتشر الشرك. ولم يكونوا يعبدون الله وحده ولا الملائكة فقط.","ow":["","عبادة الله وحده هي التوحيد.","الملائكة وحدها ليست كل ما عبدوه."]},
  {"q":"أقر المشركون بوجود الله لكنهم جعلوا الأوثان:","o":["آلهة وحدها","غير موجودة","واسطة بينهم وبينه"],"a":2,"why":"أقر المشركون بوجود الله، لكنهم جعلوا الأوثان واسطة بينهم وبينه، وهذا هو الشرك. فلم ينكروا وجود الله ولم يعدّوا الأوثان آلهة وحدها.","ow":["لم يعدّوا الأوثان آلهة وحدها بل واسطة.","لم يقولوا إنها غير موجودة، بل اتخذوها واسطة.",""]},
  {"q":"العرافة هي ادعاء معرفة:","o":["اللغات","التجارة","المغيبات"],"a":2,"why":"العرافة هي ادعاء معرفة المغيبات، أي ما غاب عن الناس، وهي ممنوعة في الإسلام. أما اللغات والتجارة فلا علاقة لهما بها.","ow":["اللغات ليست موضوع العرافة.","التجارة ليست موضوع العرافة.",""]},
  {"q":"التشاؤم يسمى:","o":["الكهانة","الطيرة","السحر"],"a":1,"why":"التشاؤم يسمى الطيرة، وكان العرب يتشاءمون من الطير. أما الكهانة فادعاء معرفة المستقبل بالجن.","ow":["الكهانة ادعاء معرفة المستقبل.","","السحر عمل مختلف عن التشاؤم."]},
  {"q":"سكان الصحراء الذين ينتقلون بحثًا عن الماء والعشب هم:","o":["الحاضرة","البادية","التجار"],"a":1,"why":"البادية هم سكان الصحراء الذين ينتقلون بحثًا عن الماء والعشب، أما الحاضرة فمستقرون في المدن والقرى.","ow":["الحاضرة مستقرون في المدن.","","التجار ليسوا هم البدو بالضرورة."]},
  {"q":"كانت رحلة الصيف إلى:","o":["اليمن","مصر","الشام"],"a":2,"why":"كانت رحلة الصيف إلى الشام ورحلة الشتاء إلى اليمن، وقد ذكرتهما سورة قريش. فمصر ليست وجهة إحدى الرحلتين.","ow":["اليمن وجهة الشتاء.","مصر ليست وجهة الرحلتين.",""]},
  {"q":"المعلقات السبع من:","o":["الحديث","الشعر الجاهلي","القرآن"],"a":1,"why":"المعلقات السبع من الشعر الجاهلي، وهي قصائد مشهورة لشعراء العرب قبل الإسلام. فليست حديثًا ولا قرآنًا.","ow":["الحديث كلام النبي ﷺ.","","القرآن كلام الله وليس شعرًا."]},
  {"q":"من أصحاب المعلقات:","o":["سيبويه","امرؤ القيس","حسان بن ثابت"],"a":1,"why":"امرؤ القيس من أصحاب المعلقات مع طرفة وزهير وعنترة وغيرهم. أما سيبويه فنحوي وحسان شاعر مخضرم مدح النبي ﷺ.","ow":["سيبويه عالم نحو جاء بعد الإسلام.","","حسان بن ثابت أسلم وليس من أصحاب المعلقات."]},
  {"q":"العبارة: كانت الحنيفية ملة إبراهيم عليه السلام وأتباعها الحنفاء.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: الحنيفية ملة إبراهيم عليه السلام وأتباعها الحنفاء، وهي ملة التوحيد.","ow":["","العبارة صحيحة، فهذا ما ذكره الكتاب."]},
  {"q":"العبارة: انتشرت اليهودية والنصرانية انتشارًا واسعًا في شبه الجزيرة العربية.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: كان انتشار اليهودية والنصرانية في شبه الجزيرة ضيقًا، ولم ينتشرا انتشارًا واسعًا.","ow":["الصحيح أن الانتشار كان ضيقًا، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: كانت مكة مركزًا للتجارة قبل الإسلام.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: كانت مكة مركزًا للتجارة قبل الإسلام، ومنها انطلقت رحلتا الشتاء والصيف.","ow":["","العبارة صحيحة، فمكة مركز التجارة."]},
  {"q":"العبارة: سوق عكاظ من أسواق العرب المشهورة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: سوق عكاظ من أسواق العرب المشهورة، ومعه مجنة وذو المجاز، وفيه كانت تُلقى القصائد.","ow":["","العبارة صحيحة، فعكاظ من أشهر الأسواق."]}
];
window.BANK['so7']['so7-4-2'] = [
  {"q":"اسم والد النبي ﷺ:","o":["هاشم","عبدالله بن عبد المطلب","أبو طالب","عبد مناف"],"a":1,"why":"والد النبي ﷺ هو عبد الله بن عبد المطلب، فاسمه الكامل محمد بن عبد الله بن عبد المطلب.","ow":["هاشم جد عبد المطلب، وليس والد النبي ﷺ.","","أبو طالب عم النبي ﷺ وليس والده.","عبد مناف جد جده."]},
  {"q":"توفي والد النبي ﷺ في:","o":["يثرب","الشام","مكة"],"a":0,"why":"توفي والد النبي ﷺ في يثرب أثناء عودته من رحلة تجارية إلى الشام، قبل أن يولد النبي ﷺ أو بعد ولادته بقليل بحسب الروايات.","ow":["","لم يتوفَّ في الشام بل في يثرب في طريق العودة.","لم يتوفَّ في مكة بل في يثرب."]},
  {"q":"وُلد النبي ﷺ في عام:","o":["الفيل","الحزن","الفتح"],"a":0,"why":"وُلد النبي ﷺ في عام الفيل، وهو العام الذي غزا فيه أبرهة مكة ويوافق سنة 571م. أما عام الحزن فبعد البعثة وعام الفتح سنة 8 هـ.","ow":["","عام الحزن حين توفيت خديجة وأبو طالب.","عام الفتح هو فتح مكة."]},
  {"q":"وُلد النبي ﷺ في:","o":["الطائف","مكة المكرمة","المدينة المنورة"],"a":1,"why":"وُلد النبي ﷺ في مكة المكرمة في ربيع الأول من عام الفيل، وهاجر إلى المدينة المنورة بعد ذلك، فلم يولد في الطائف ولا المدينة.","ow":["الطائف ليست مكان ميلاده.","","المدينة المنورة هاجر إليها بعد ذلك."]},
  {"q":"الذي سمّاه محمدًا:","o":["عمه أبو طالب","أبوه","جده عبد المطلب"],"a":2,"why":"سمّاه جده عبد المطلب محمدًا، فهو اسم لم يكن مألوفًا عند العرب آنذاك. أما أبوه فقد توفي قبل أن يعيش معه ويسميه.","ow":["عمه أبو طالب لم يسمّه محمدًا.","أبوه توفي قبل أن يسميه أو بعد ولادته بقليل.",""]},
  {"q":"ينتهي نسب النبي ﷺ إلى:","o":["قحطان","سام","عدنان ثم إسماعيل بن إبراهيم"],"a":2,"why":"ينتهي نسب النبي ﷺ إلى عدنان ثم إسماعيل بن إبراهيم عليهما السلام، فهو من العرب العدنانية.","ow":["قحطان جد العرب القحطانية.","سام جد الساميين وليس هو المقصود هنا.",""]},
  {"q":"اصطفى الله من العرب كنانة ثم:","o":["ثقيف","قريشًا ثم بني هاشم","الأوس"],"a":1,"why":"اصطفى الله من ذرية إسماعيل كنانة ثم قريشًا ثم بني هاشم ثم محمدًا ﷺ، فهو من أشرف الأنساب.","ow":["ثقيف ليست في هذا الاصطفاء.","","الأوس من الأنصار وليسوا في هذا النسب."]},
  {"q":"كان أشراف العرب يرسلون أبناءهم للمرضعات في البادية لـ:","o":["سلامة اللغة وفصاحة اللسان وصحة الجسد","الحرب","التجارة"],"a":0,"why":"كان أشراف العرب يرسلون أبناءهم إلى المرضعات في البادية لسلامة اللغة وفصاحة اللسان وصحة الجسد، لا للحرب أو التجارة.","ow":["","الحرب ليست سبب إرسالهم.","التجارة ليست سبب إرسالهم."]},
  {"q":"توفيت أم النبي ﷺ وعمره:","o":["12 سنة","6 سنوات","25 سنة"],"a":1,"why":"توفيت أم النبي ﷺ آمنة بنت وهب وعمره ست سنوات، فنشأ يتيمًا ثم كفله جده عبد المطلب، ثم عمه أبو طالب بعد وفاة جده.","ow":["12 سنة عمره في رحلة الشام.","","25 سنة عمره عند زواجه من خديجة."]},
  {"q":"توفي جده عبد المطلب بعد وفاة أمه بنحو:","o":["شهر","سنتين","عشر سنوات"],"a":1,"why":"توفي جده عبد المطلب بعد وفاة أمه بنحو سنتين، ثم انتقلت الكفالة إلى عمه أبي طالب.","ow":["شهر مدة قصيرة جدًا.","","عشر سنوات مدة طويلة."]},
  {"q":"كفل النبي ﷺ عمه أبو طالب بـ:","o":["وصية من جده","طلب من قريش","قرعة"],"a":0,"why":"كفل أبو طالب النبي ﷺ بوصية من جده عبد المطلب قبل وفاته، لا بقرعة ولا بطلب من قريش، وكان يعامله معاملة أبنائه.","ow":["","قريش لم تطلب منه ذلك.","القرعة لم تكن طريقة الكفالة."]},
  {"q":"كان النبي ﷺ يتعبد قبل الوحي في:","o":["غار حراء","غار ثور","مسجد قباء"],"a":0,"why":"كان النبي ﷺ يتعبد قبل الوحي في غار حراء بجبل النور قرب مكة، أما غار ثور فاختبأ فيه وقت الهجرة، ومسجد قباء بُني بعدها.","ow":["","غار ثور في الهجرة.","مسجد قباء بُني بعد الهجرة."]},
  {"q":"رعى النبي ﷺ الغنم صغيرًا لـ:","o":["اللعب","تخفيف نفقات عمه","الاستمتاع بالرحلات"],"a":1,"why":"رعى النبي ﷺ الغنم صغيرًا لتخفيف نفقات عمه، فتعلم المسؤولية والصبر. فلم يكن للّعب أو الاستمتاع.","ow":["اللعب ليس سبب رعيه الغنم.","","الاستمتاع بالرحلات ليس السبب."]},
  {"q":"تاجر النبي ﷺ في مال خديجة مع غلامها:","o":["ميسرة","زيد","بلال"],"a":0,"why":"تاجر النبي ﷺ في مال خديجة مع غلامها ميسرة وعاد بأرباح كثيرة، فأعجبت بأمانته وتزوجها.","ow":["","زيد ليس غلام خديجة في التجارة.","بلال ليس غلام خديجة."]},
  {"q":"لُقّب النبي ﷺ بـ «الأمين» عندما:","o":["عاد من الشام","تزوج خديجة","اتفقت القبائل على حكمه في وضع الحجر الأسود"],"a":2,"why":"لُقّب النبي ﷺ بـ«الأمين» عندما اختلفت القبائل في وضع الحجر الأسود، فقالوا: جاءكم الأمين، فوضعه في ثوب ورفعوه جميعًا.","ow":["العودة من الشام ليست سبب اللقب.","الزواج من خديجة ليس سبب اللقب.",""]},
  {"q":"من أبناء النبي ﷺ:","o":["عثمان","الحسن","القاسم"],"a":2,"why":"من أبناء النبي ﷺ القاسم وعبد الله وإبراهيم، أما عثمان فصهره (زوج ابنتيه رقية وأم كلثوم) والحسن حفيده من ابنته فاطمة.","ow":["عثمان زوج ابنتيه رقية وأم كلثوم.","الحسن حفيده من ابنته فاطمة.",""]},
  {"q":"العبارة: حضر النبي ﷺ قبل البعثة حلفًا للتعاهد على نصرة المظلوم.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: حضر النبي ﷺ حلف الفضول قبل البعثة، وقال إنه لو دُعي إليه في الإسلام لأجاب.","ow":["","العبارة صحيحة، فالنبي ﷺ حضر الحلف."]},
  {"q":"العبارة: وُلد النبي ﷺ في المدينة المنورة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: وُلد النبي ﷺ في مكة المكرمة، ثم هاجر إلى المدينة المنورة بعد البعثة بنحو ثلاث عشرة سنة، فالمدينة ليست مكان ميلاده.","ow":["الصحيح أنه ولد في مكة، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: عصم الله النبي ﷺ من أفعال الجاهلية.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: عصم الله النبي ﷺ من أفعال الجاهلية، فنشأ كريم الخلق ويتعبد في غار حراء.","ow":["","العبارة صحيحة، فقد ذكر الكتاب ذلك."]},
  {"q":"العبارة: تزوج النبي ﷺ خديجة وعمره 40 سنة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: تزوج النبي ﷺ خديجة وعمره 25 سنة، أما 40 سنة فعمره عند نزول الوحي عليه في غار حراء.","ow":["الصحيح أن عمره 25 سنة عند زواجه، فالعبارة غير صحيحة.",""]}
];
window.BANK['so7']['so7-4-3'] = [
  {"q":"بدأ الوحي على النبي ﷺ بـ:","o":["نزول جبريل مباشرة","سماع صوت","الرؤيا الصادقة"],"a":2,"why":"بدأ الوحي على النبي ﷺ بالرؤيا الصادقة، فكان لا يرى رؤيا إلا جاءت مثل فلق الصبح، ثم نزل جبريل.","ow":["لم يبدأ بنزول جبريل مباشرة.","لم يبدأ بسماع صوت فقط.",""]},
  {"q":"كانت الرؤيا الصادقة تأتيه مثل:","o":["الرياح","الرعد","فلق الصبح"],"a":2,"why":"كانت الرؤيا الصادقة تأتيه مثل فلق الصبح، أي ضوء الفجر، وتتحقق وضوحًا كوضوحه. فهي ليست كالرياح ولا كالرعد.","ow":["الرياح ليست تشبيهها.","الرعد ليس تشبيهها.",""]},
  {"q":"نزل الوحي في شهر:","o":["ربيع الأول","ذي الحجة","رمضان"],"a":2,"why":"نزل الوحي على النبي ﷺ في شهر رمضان من عام 610م، ولذلك سُمّي رمضان شهر القرآن. أما ربيع الأول فشهر ميلاده ووفاته.","ow":["ربيع الأول شهر ميلاده ﷺ.","ذو الحجة شهر الحج.",""]},
  {"q":"مكان نزول الوحي:","o":["المسجد الحرام","غار حراء","الصفا"],"a":1,"why":"نزل الوحي في غار حراء بجبل النور قرب مكة، حيث كان النبي ﷺ يتعبد قبل البعثة. أما الصفا فمكان إعلان الدعوة.","ow":["المسجد الحرام ليس مكان نزول الوحي.","","الصفا مكان إعلان الدعوة."]},
  {"q":"غطّ جبريل عليه السلام النبي ﷺ:","o":["مرة واحدة","ثلاث مرات","سبع مرات"],"a":1,"why":"غطّ جبريل عليه السلام النبي ﷺ ثلاث مرات، وفي الثالثة قرأ: ﴿اقرأ باسم ربك الذي خلق﴾.","ow":["لم يغطه مرة واحدة فقط.","","لم يغطه سبع مرات."]},
  {"q":"قالت خديجة: «كلا والله ما يخزيك الله أبدًا» لأنه:","o":["ضعيف","يصل الرحم ويحمل الكل ويقري الضيف","غني"],"a":1,"why":"قالت خديجة: «كلا والله ما يخزيك الله أبدًا» لأنه يصل الرحم ويحمل الكل ويقري الضيف، فذكرت صفاته الطيبة لتطمئنه.","ow":["لم تذكر ضعفه فهو قوي.","","لم تقل إنه غني في هذا الموقف."]},
  {"q":"قال ورقة بن نوفل: «هذا الناموس» ويقصد به:","o":["ملك الموت","عيسى عليه السلام","جبريل عليه السلام"],"a":2,"why":"قال ورقة بن نوفل: «هذا الناموس»، ويقصد جبريل عليه السلام صاحب السر الذي نزل على موسى.","ow":["ملك الموت غير جبريل.","عيسى عليه السلام نبي وليس الناموس.",""]},
  {"q":"أول من أسلم من الرجال الأحرار:","o":["عمر بن الخطاب","خالد بن الوليد","أبو بكر الصديق"],"a":2,"why":"أول من أسلم من الرجال الأحرار أبو بكر الصديق، ثم عثمان والزبير وطلحة وأبو عبيدة.","ow":["عمر أسلم لاحقًا بعد الدعوة الجهرية.","خالد بن الوليد أسلم بعد ذلك بسنوات.",""]},
  {"q":"بلال وصهيب وعمار من:","o":["أشراف قريش","الموالي","الأنصار"],"a":1,"why":"بلال وصهيب وعمار من الموالي الذين أسلموا، فعذّبتهم قريش لضعفهم، وصبروا على دينهم.","ow":["أشراف قريش لم يكونوا منهم.","","الأنصار هم أهل المدينة."]},
  {"q":"أمر الله نبيه ﷺ بدعوة أقاربه بقوله: ﴿وأنذر ...﴾:","o":["عشيرتك الأقربين","قومك أجمعين","الناس كافة"],"a":0,"why":"أمر الله نبيه بقوله: ﴿وأنذر عشيرتك الأقربين﴾، فدعا أقاربه أولًا ثم أعلن الدعوة من الصفا.","ow":["","﴿قومك أجمعين﴾ ليس نص الآية.","﴿الناس كافة﴾ ليس نص هذه الآية."]},
  {"q":"عندما كذّبه أبو لهب وقال: «تبًّا لك» نزلت سورة:","o":["المسد","الفاتحة","الإخلاص"],"a":0,"why":"لما كذّبه أبو لهب وقال: «تبًّا لك» نزلت سورة المسد في ذمّه وتوعّده، أما الفاتحة والإخلاص فليستا ردًّا عليه.","ow":["","الفاتحة ليست الرد على أبي لهب.","الإخلاص ليست الرد على أبي لهب."]},
  {"q":"دخل في الإسلام بعد رفض قريش للدعوة:","o":["أبو جهل","حمزة وعمر","أبو لهب"],"a":1,"why":"أسلم حمزة وعمر بعد رفض قريش للدعوة، فقوي بهما الإسلام. أما أبو جهل وأبو لهب فبقيا على عداوتهما.","ow":["أبو جهل بقي عدوًّا للنبي ﷺ.","","أبو لهب بقي عدوًّا للنبي ﷺ."]},
  {"q":"من وسائل قريش في محاربة الدعوة:","o":["مساعدة المسلمين","السخرية والاستهزاء واضطهاد الأتباع","ترك الأذى"],"a":1,"why":"من وسائل قريش في محاربة الدعوة السخرية والاستهزاء واضطهاد الأتباع وتعذيبهم وتشويه الدعوة والاعتداء على النبي ﷺ.","ow":["مساعدة المسلمين ضد ما فعلته قريش.","","ترك الأذى ضد ما فعلته قريش."]},
  {"q":"هاجر بعض الصحابة إلى الحبشة لأن ملكها:","o":["يعبد الأصنام","لا يظلم عنده أحد","من قريش"],"a":1,"why":"هاجر بعض الصحابة إلى الحبشة لأن ملكها لا يظلم عنده أحد، فكانت مأمنًا لهم من أذى قريش.","ow":["ملكها لم يعبد الأصنام بحسب الدرس.","","ملكها ليس من قريش."]},
  {"q":"منعت قريش في المقاطعة التعامل مع:","o":["ثقيف","بني هاشم وبني المطلب","الأوس"],"a":1,"why":"منعت قريش في المقاطعة التعامل مع بني هاشم وبني المطلب، فلا زواج ولا بيع ولا شراء، لأنهم حموا النبي ﷺ.","ow":["ثقيف لم تشملها المقاطعة.","","الأوس لم تشملهم المقاطعة."]},
  {"q":"عدد النقباء الذين اختارهم أهل يثرب:","o":["12","73","2"],"a":0,"why":"اختار أهل يثرب في بيعة العقبة الثانية اثني عشر نقيبًا يتحملون المسؤولية. أما 73 فعدد المبايعين.","ow":["","73 هو عدد الرجال المبايعين.","2 عدد النساء المبايعات وليس النقباء."]},
  {"q":"العبارة: أسلم علي بن أبي طالب وعمره 10 سنوات.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: أسلم علي بن أبي طالب وعمره عشر سنوات، فهو أول من أسلم من الصبيان.","ow":["","العبارة صحيحة، فقد ذكر الكتاب ذلك."]},
  {"q":"العبارة: انتهى حصار الشعب بإخفاق قريش.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: انتهى حصار الشعب بإخفاق قريش، فلم تحقق مقاطعتها لبني هاشم وبني المطلب هدفها، وبقي النبي ﷺ ثابتًا في دعوته.","ow":["","العبارة صحيحة، فقد فشلت المقاطعة."]},
  {"q":"العبارة: بايع في بيعة العقبة الأولى 73 رجلًا.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: بايع في العقبة الأولى اثنا عشر رجلًا، أما 73 رجلًا وامرأتان ففي العقبة الثانية.","ow":["الصحيح أن الأولى 12 رجلًا، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: أرسل النبي ﷺ مصعب بن عمير يعلّم أهل يثرب القرآن.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: أرسل النبي ﷺ مصعب بن عمير بعد بيعة العقبة الأولى يعلّم أهل يثرب القرآن والدين.","ow":["","العبارة صحيحة، فمصعب كان المعلم."]}
];
window.BANK['so7']['so7-4-4'] = [
  {"q":"من أسباب الهجرة:","o":["ازدياد أذى قريش واتفاقهم على قتل النبي ﷺ","حب السفر","الرحلات التجارية"],"a":0,"why":"من أسباب الهجرة ازدياد أذى قريش واتفاقهم على قتل النبي ﷺ، مع ضعف الأمل في نصرة أهل مكة للدعوة.","ow":["","حب السفر ليس سبب الهجرة.","الرحلات التجارية ليست سبب الهجرة."]},
  {"q":"انتشر الإسلام في يثرب فأمر الله النبي ﷺ بـ:","o":["الهجرة إليها","الذهاب إلى الحبشة","البقاء في مكة"],"a":0,"why":"انتشر الإسلام في يثرب فأمر الله النبي ﷺ بالهجرة إليها، لأنها صارت أرضًا مهيأة للدعوة.","ow":["","الحبشة هاجر إليها بعض الصحابة قبل ذلك.","البقاء في مكة لم يعد آمنًا."]},
  {"q":"تُعد الهجرة حدثًا مهمًّا لأنه:","o":["انتهى الإسلام","تأسست بعدها الدولة الإسلامية وانتشر الإسلام","توقفت الدعوة"],"a":1,"why":"الهجرة حدث مهم لأن الدولة الإسلامية تأسست بعدها وانتشر الإسلام. فلم ينته الإسلام ولم تتوقف الدعوة.","ow":["الإسلام لم ينتهِ بعد الهجرة.","","الدعوة لم تتوقف بل ازدهرت."]},
  {"q":"من دروس الهجرة أن المسلم:","o":["يترك الدعوة","لا ييأس من رحمة الله","يستسلم"],"a":1,"why":"من دروس الهجرة أن المسلم لا ييأس من رحمة الله مهما اشتدت الصعاب، فبعد الشدة جاء الفرج.","ow":["ترك الدعوة ليس من دروس الهجرة.","","الاستسلام ضد روح الهجرة."]},
  {"q":"يدل اللجوء إلى النجاشي على جواز:","o":["الظلم","ترك الأمانة","الاستفادة من الإمكانات خارج بلاد المسلمين"],"a":2,"why":"اللجوء إلى النجاشي يدل على جواز الاستفادة من الإمكانات خارج بلاد المسلمين، كعدل ملك الحبشة.","ow":["الظلم محرم ولا يجوز، وليس هذا هو ما يدل عليه اللجوء إلى النجاشي.","ترك الأمانة لا يجوز.",""]},
  {"q":"من دلائل ذكائه ﷺ في الهجرة:","o":["ذهب مع قريش","سلك طرقًا غير معهودة","سار مع القافلة"],"a":1,"why":"من دلائل ذكاء النبي ﷺ في الهجرة أنه سلك طرقًا غير معهودة، فلم تصل إليه قريش، مع حفظ الله له.","ow":["الذهاب مع قريش ليس من الذكاء ولا من الواقع.","","السير مع القافلة طريق معروف لقريش."]},
  {"q":"المسجد النبوي مكان للعبادة وكذلك:","o":["سجن","مركز للحكم والقيادة","سوق"],"a":1,"why":"المسجد النبوي مكان للعبادة ومركز للحكم والقيادة، ففيه تُقام الصلاة وتُدار شؤون الدولة.","ow":["السجن ليس من وظائفه.","","السوق ليس من وظائفه."]},
  {"q":"عاصمة البلاد الإسلامية بعد الهجرة:","o":["المدينة المنورة","دمشق","مكة المكرمة"],"a":0,"why":"صارت المدينة المنورة عاصمة البلاد الإسلامية بعد الهجرة، ومنها انطلقت الدولة والفتوحات.","ow":["","دمشق صارت عاصمة في الدولة الأموية.","مكة كانت مركز الدعوة قبل الهجرة وفتحت بعد ذلك."]},
  {"q":"المهاجرون هم الذين جاؤوا من:","o":["الحبشة","مكة","المدينة"],"a":1,"why":"المهاجرون هم الذين هاجروا من مكة إلى المدينة، تاركين أموالهم وديارهم من أجل دينهم.","ow":["الحبشة هاجر إليها بعض الصحابة لكنهم ليسوا المقصودين هنا.","","المدينة هي موطن الأنصار."]},
  {"q":"الأنصار هم:","o":["أهل مكة","أهل المدينة","أهل الشام"],"a":1,"why":"الأنصار هم أهل المدينة الذين نصروا النبي ﷺ والمهاجرين وآووهم، أما المهاجرون فجاؤوا من مكة وتركوا أموالهم وديارهم.","ow":["أهل مكة هم قريش.","","أهل الشام ليسوا الأنصار."]},
  {"q":"أي مما يأتي من بنود المؤاخاة؟","o":["الاحتكام للعرف","الولاء للإسلام لا للقبيلة","الولاء للقبيلة"],"a":1,"why":"من بنود المؤاخاة الولاء للإسلام لا للقبيلة والاحتكام للشرع لا للعرف، فصار الإسلام هو الرابطة بين المهاجرين والأنصار.","ow":["الاحتكام للعرف ضد المؤاخاة.","","الولاء للقبيلة ضد المؤاخاة."]},
  {"q":"من فوائد المؤاخاة:","o":["التنافس على المال","المواساة وتقوية أواصر المودة","الفرقة"],"a":1,"why":"من فوائد المؤاخاة المواساة وتقوية أواصر المودة بين المهاجرين والأنصار. أما التنافس على المال والفرقة فتضعف الوحدة.","ow":["التنافس على المال ضد المؤاخاة.","","الفرقة ضد المؤاخاة."]},
  {"q":"عقد النبي ﷺ معاهدة مع يهود بني قينقاع وبني النضير و:","o":["بني حنيفة","بني ثقيف","بني قريظة"],"a":2,"why":"عقد النبي ﷺ معاهدة مع يهود بني قينقاع وبني النضير وبني قريظة، وهي من وثيقة المدينة. أما بنو حنيفة وثقيف فليسوا منهم.","ow":["بنو حنيفة قبيلة في اليمامة.","ثقيف قبيلة في الطائف.",""]},
  {"q":"من بنود وثيقة المدينة:","o":["إجبار على الإسلام","منع العبادة","حرية العبادة والعيش في أمن وسلام"],"a":2,"why":"من بنود وثيقة المدينة حرية العبادة والعيش في أمن وسلام، وعون المدينة في صد العدوان وتجنب التآمر على المسلمين.","ow":["الإجبار على الإسلام ضد وثيقة المدينة.","منع العبادة ضد وثيقة المدينة.",""]},
  {"q":"بداية السنة الهجرية شهر:","o":["المحرم","ربيع الأول","رمضان"],"a":0,"why":"بداية السنة الهجرية شهر المحرم، وهو الشهر الأول في التقويم الهجري، أما ربيع الأول فشهر الهجرة نفسها ورمضان شهر الصيام.","ow":["","ربيع الأول شهر الهجرة نفسها لكنه ليس بداية السنة.","رمضان شهر الصيام وليس بداية السنة."]},
  {"q":"اختير المحرم بداية للسنة الهجرية لأنه:","o":["وقت انصراف الناس من الحج","وقت الحرب","وقت الصيام"],"a":0,"why":"اختير المحرم بداية للسنة الهجرية لأنه وقت انصراف الناس من الحج، فيجتمعون على الأمر بعد انتهاء الموسم.","ow":["","الحرب ليست سبب اختياره.","الصيام ليس سبب اختياره."]},
  {"q":"العبارة: نهى النبي ﷺ عن تسمية المدينة بيثرب.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: نهى النبي ﷺ عن تسمية المدينة بيثرب، وسماها المدينة وطيبة، فصار اسمها المدينة المنورة بعد الهجرة.","ow":["","العبارة صحيحة، فقد نهى عن الاسم القديم."]},
  {"q":"العبارة: بدأ التأريخ بالهجرة في عهد أبي بكر الصديق.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: بدأ التأريخ بالهجرة في عهد عمر بن الخطاب لا في عهد أبي بكر، وجعلوا بداية السنة شهر المحرم.","ow":["الصحيح أن البداية في عهد عمر، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: حفظ الله نبيه ﷺ فلم تصل إليه قريش في طريق الهجرة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: حفظ الله نبيه ﷺ في طريق الهجرة فلم تصل إليه قريش، وهذا من دروس الهجرة.","ow":["","العبارة صحيحة، فهذا ما ذكره الكتاب."]},
  {"q":"العبارة: المؤاخاة كانت بين المهاجرين والأنصار.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: المؤاخاة كانت بين المهاجرين والأنصار، فآخى النبي ﷺ بينهم ليتعاونوا.","ow":["","العبارة صحيحة، فهذا هو معنى المؤاخاة."]}
];
window.BANK['so7']['so7-4-5'] = [
  {"q":"السرية هي الحملة التي:","o":["قادها أبو بكر بعد وفاته","قادها بنفسه","وجهها النبي ﷺ ولم يحضرها بنفسه"],"a":2,"why":"السرية هي الحملة التي وجّهها النبي ﷺ ولم يحضرها بنفسه، أما الغزوة فهي التي قادها بنفسه، وهذا هو الفرق بينهما.","ow":["أبو بكر لم يقد السرية بعد وفاة النبي ﷺ لتسمى سرية.","الحملة التي قادها بنفسه تسمى غزوة.",""]},
  {"q":"من أسباب غزوة بدر استيلاء قريش على:","o":["الأنصار","أموال المسلمين المهاجرين","المسجد الحرام"],"a":1,"why":"من أسباب غزوة بدر استيلاء قريش في مكة على أموال المسلمين المهاجرين، فأراد النبي ﷺ اعتراض قافلتهم.","ow":["الأنصار ليسوا من استولت قريش على أموالهم.","","المسجد الحرام لم تستول عليه قريش."]},
  {"q":"أراد النبي ﷺ في بدر اعتراض قافلة:","o":["أبي لهب","أبي جهل","أبي سفيان"],"a":2,"why":"أراد النبي ﷺ في بدر اعتراض قافلة أبي سفيان القادمة من الشام، فنجا بها أبو سفيان.","ow":["أبو لهب لم يقد القافلة.","أبو جهل قاد الجيش لا القافلة.",""]},
  {"q":"نجا أبو سفيان بقافلته عن طريق:","o":["الصحراء","الساحل","الجبل"],"a":1,"why":"نجا أبو سفيان بالقافلة عن طريق الساحل، فلم يلحق به المسلمون، وبقي القتال مع أبي جهل.","ow":["لم يسر في الصحراء المعتادة.","","لم يسر عن طريق الجبل."]},
  {"q":"الذي أصرّ على القتال في بدر:","o":["أبو لهب","أبو جهل","أبو سفيان"],"a":1,"why":"الذي أصرّ على القتال في بدر هو أبو جهل، رغم نجاة القافلة بطريق الساحل، فكانت المعركة بين المسلمين وقريش.","ow":["أبو لهب لم يحضر بدرًا.","","أبو سفيان نجا بالقافلة وطلب العودة."]},
  {"q":"بلغ عدد جيش المشركين في بدر:","o":["10000 مقاتل","1000 مقاتل","3000 مقاتل"],"a":1,"why":"بلغ جيش المشركين في بدر نحو 1000 مقاتل بقيادة أبي جهل، والمسلمون 319 فقط، ومع ذلك انتصر المسلمون بتوفيق الله.","ow":["10000 عدد جيش فتح مكة.","","3000 عدد جيش المشركين في أحد."]},
  {"q":"وقعت غزوة بدر في السنة:","o":["3 هـ","8 هـ","2 هـ","5 هـ"],"a":2,"why":"وقعت غزوة بدر في السنة الثانية للهجرة، وأحد الثالثة والخندق الخامسة وفتح مكة الثامنة.","ow":["3 هـ هي سنة غزوة أحد وليست سنة بدر.","8 هـ سنة فتح مكة.","","5 هـ سنة الخندق."]},
  {"q":"سبب غزوة أحد:","o":["فتح مكة","حصار المدينة","انتقام قريش لهزيمتها في بدر"],"a":2,"why":"سبب غزوة أحد انتقام قريش لهزيمتها في بدر، فجمعت جيشًا كبيرًا من ثلاثة آلاف وخرجت إلى المدينة بقيادة أبي سفيان.","ow":["فتح مكة كان بعدها بسنوات.","حصار المدينة كان في الخندق.",""]},
  {"q":"بلغ عدد المسلمين في غزوة أحد:","o":["3000 مقاتل","319 مقاتلًا","700 مقاتل"],"a":2,"why":"بلغ عدد المسلمين في غزوة أحد نحو 700 مقاتل، بينما بلغ عدد المشركين 3000، وكان النبي ﷺ قائد المسلمين.","ow":["3000 عدد المشركين في أحد.","319 عدد المسلمين في بدر.",""]},
  {"q":"وضع النبي ﷺ على الجبل في أحد:","o":["50 راميًا","500 رام","5 رماة"],"a":0,"why":"وضع النبي ﷺ على الجبل في أحد خمسين راميًا ليحموا ظهر الجيش، وأمرهم ألا يتركوا مواقعهم مهما حدث.","ow":["","500 رام أكثر بكثير من العدد.","5 رماة أقل بكثير من العدد."]},
  {"q":"الذي التفّ خلف الجبل وهاجم المسلمين في أحد (قبل إسلامه):","o":["خالد بن الوليد","أبو سفيان","عمرو بن العاص"],"a":0,"why":"خالد بن الوليد، قبل إسلامه، التف خلف الجبل وهاجم المسلمين حين ترك الرماة مواقعهم.","ow":["","أبو سفيان قاد المشركين لكنه لم يلتف خلف الجبل.","عمرو بن العاص لم يكن قائد هذه الحركة."]},
  {"q":"الدرس المستفاد من أحد:","o":["الاعتماد على الغنائم","طاعة أمر القائد","ترك الجبل"],"a":1,"why":"الدرس المستفاد من أحد طاعة أمر القائد، فقد خسر المسلمون لما خالف الرماة أمر النبي ﷺ.","ow":["الاعتماد على الغنائم هو الخطأ الذي وقع فيه الرماة.","","ترك الجبل هو سبب الهزيمة."]},
  {"q":"كان عدد المسلمين في الخندق:","o":["700","3000","1400"],"a":1,"why":"كان عدد المسلمين في الخندق ثلاثة آلاف، وعدد الأحزاب عشرة آلاف، فاحتاجوا إلى الخندق للدفاع.","ow":["700 عدد المسلمين في أحد.","","1400 عدد المسلمين في الحديبية."]},
  {"q":"الذي اقتلع خيام الأحزاب في الخندق:","o":["ريح باردة","نار","سيل"],"a":0,"why":"أرسل الله ريحًا باردة اقتلعت خيام الأحزاب في الخندق وأطفأت نيرانهم، فرجعوا خائبين، فكان ذلك نصرًا للمسلمين.","ow":["","لم تحرق الأحزابَ نارٌ، وإنما أرسل الله عليهم ريحًا باردة.","لم يكن السبب سيلًا."]},
  {"q":"تصدى لفرسان الأحزاب في الخندق:","o":["عمر","أبو بكر","علي بن أبي طالب"],"a":2,"why":"تصدى علي بن أبي طالب لفرسان الأحزاب في الخندق، وقد اشتهر بشجاعته، أما عمر وأبو بكر فلم يُذكرا في هذا الموقف.","ow":["عمر لم يُذكر في هذا الموقف.","أبو بكر لم يُذكر في هذا الموقف.",""]},
  {"q":"وقعت غزوة الخندق في السنة:","o":["5 هـ","8 هـ","2 هـ"],"a":0,"why":"وقعت غزوة الخندق في السنة الخامسة للهجرة، وسُميت غزوة الأحزاب لاجتماع القبائل على قتال المسلمين.","ow":["","8 هـ سنة فتح مكة.","2 هـ هي سنة غزوة بدر وليست الخندق."]},
  {"q":"خرج النبي ﷺ للعمرة سنة 6 هـ مع نحو:","o":["3000 مسلم","1400 مسلم","10000 مسلم"],"a":1,"why":"خرج النبي ﷺ سنة 6 هـ للعمرة مع نحو 1400 من المسلمين، فمنعتهم قريش فكان صلح الحديبية.","ow":["3000 عدد جيش المسلمين في الخندق.","","10000 عدد جيش فتح مكة."]},
  {"q":"اعتدى بنو بكر بمساعدة قريش على:","o":["ثقيف","خزاعة","الأوس"],"a":1,"why":"اعتدى بنو بكر بمساعدة قريش على خزاعة وهم حلفاء النبي ﷺ، فنقضت قريش صلح الحديبية، فكان ذلك سببًا لفتح مكة.","ow":["ثقيف ليست من اعتُدي عليها.","","الأوس ليسوا من اعتُدي عليهم."]},
  {"q":"قال النبي ﷺ لقريش في فتح مكة: «لا تثريب عليكم اليوم،»:","o":["اذهبوا فأنتم الطلقاء","سنقاتلكم","اخرجوا من مكة"],"a":0,"why":"قال النبي ﷺ لقريش في فتح مكة: «لا تثريب عليكم اليوم، اذهبوا فأنتم الطلقاء»، فعفا عنهم.","ow":["","لم يقل: سنقاتلكم، بل عفا.","لم يطلب منهم الخروج من مكة."]},
  {"q":"دخل النبي ﷺ مكة في الفتح:","o":["مطأطئ الرأس تواضعًا لله","رافعًا رأسه فخرًا","متخفيًا"],"a":0,"why":"دخل النبي ﷺ مكة مطأطئ الرأس تواضعًا لله، لا فخرًا ولا خفية، وذلك يعلّمنا التواضع عند النصر وعدم التكبر.","ow":["","لم يدخلها رافعًا رأسه فخرًا.","لم يدخلها متخفيًا بل ظاهرًا في جيش."]},
  {"q":"العبارة: بلغ عدد جيش فتح مكة 10000 مقاتل.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: بلغ عدد جيش فتح مكة عشرة آلاف مقاتل، دخلوا مكة من أربع فرق، وهو أكبر جيش للمسلمين حتى ذلك الوقت.","ow":["","العبارة صحيحة، فالعدد عشرة آلاف."]},
  {"q":"العبارة: انتصر المسلمون في غزوة بدر.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: انتصر المسلمون في غزوة بدر مع قلة عددهم، فهم 319 مقابل 1000، وكانت أول معركة كبرى في الإسلام.","ow":["","العبارة صحيحة، فقد انتصروا في بدر."]},
  {"q":"العبارة: حطّم النبي ﷺ الأصنام وطهّر البيت الحرام بعد فتح مكة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: حطّم النبي ﷺ الأصنام وطهّر البيت الحرام بعد فتح مكة وصلى في الكعبة.","ow":["","العبارة صحيحة، فقد طهّر البيت الحرام."]},
  {"q":"العبارة: كان العام التاسع الهجري يسمى عام الوفود.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: سُمّي العام التاسع الهجري عام الوفود، حيث أقبل الناس على الإسلام أفواجًا.","ow":["","العبارة صحيحة، فهذا اسم العام التاسع."]}
];
window.BANK['so7']['so7-4-6'] = [
  {"q":"وصف الله نبيه ﷺ بقوله: ﴿وإنك لعلى ...﴾:","o":["مال وفير","علم كثير","خلق عظيم"],"a":2,"why":"قال تعالى: ﴿وإنك لعلى خلق عظيم﴾، فوصف الله نبيه ﷺ بالخلق العظيم، لا بالمال ولا بالعلم الكثير.","ow":["المال ليس مما وصفه به في الآية.","العلم الكثير ليس مما وصفه به في الآية.",""]},
  {"q":"قدوة المسلمين جميعًا هو:","o":["النبي محمد ﷺ","أبو لهب","قريش"],"a":0,"why":"قدوة المسلمين جميعًا النبي محمد ﷺ، لأن الله شهد له بالخلق العظيم. أما أبو لهب فعدوه وقريش قبيلته.","ow":["","أبو لهب كان عدوًّا للنبي ﷺ.","قريش قبيلة وليست قدوة المسلمين."]},
  {"q":"قالت قريش على الصفا: «ما جربنا عليك إلا ...»:","o":["كذبًا","غضبًا","صدقًا"],"a":2,"why":"قالت قريش على الصفا: «ما جربنا عليك إلا صدقًا»، فشهدوا بصدقه قبل أن يعلن الدعوة، وهذا هو سبب لقبه الصادق الأمين.","ow":["لم يقولوا إنهم جربوا عليه كذبًا.","لم يقولوا إنهم جربوا عليه غضبًا.",""]},
  {"q":"أنواع الصدق:","o":["مع الأصدقاء فقط","في التجارة فقط","مع الله ومع النفس ومع الناس"],"a":2,"why":"الصدق أنواع: مع الله ومع النفس ومع الناس، فلا يقتصر على الأصدقاء ولا على التجارة.","ow":["الصدق ليس مع الأصدقاء فقط.","الصدق ليس في التجارة فقط.",""]},
  {"q":"من مظاهر تواضع النبي ﷺ أنه كان:","o":["يجالس الفقراء ويأكل مع المساكين","يرفض زيارة المرضى","يجلس وحده"],"a":0,"why":"من تواضع النبي ﷺ أنه كان يجالس الفقراء ويأكل مع المساكين ويعود المرضى، ولم يكن يرفض زيارتهم.","ow":["","لم يرفض زيارة المرضى بل كان يعودهم.","لم يكن يجلس وحده بل مع الناس."]},
  {"q":"كان النبي ﷺ يمازح:","o":["الصبيان ويسلم عليهم","أصحابه الكبار فقط","الأغنياء فقط"],"a":0,"why":"كان النبي ﷺ يمازح الصبيان ويسلم عليهم، وهذا من تواضعه ورحمته. فلم يقتصر على الكبار أو الأغنياء.","ow":["","لم يقتصر على الكبار.","لم يقتصر على الأغنياء."]},
  {"q":"كان النبي ﷺ في بيته:","o":["لا يعمل شيئًا","يأمر الخدم بكل شيء","يخيط ثوبه ويخصف نعله"],"a":2,"why":"كان النبي ﷺ في بيته يخيط ثوبه ويخصف نعله، أي يصلحه، فلا يستنكف من العمل لنفسه. وهذا من تواضعه.","ow":["لم يكن لا يعمل شيئًا.","لم يكن يأمر الخدم بكل شيء.",""]},
  {"q":"قال النبي ﷺ: «من كان يؤمن بالله واليوم الآخر فليحسن إلى ...»:","o":["جاره","عمله","ماله"],"a":0,"why":"قال النبي ﷺ: «من كان يؤمن بالله واليوم الآخر فليحسن إلى جاره»، فالإحسان إلى الجار من الإيمان.","ow":["","العمل ليس المقصود بالإحسان في الحديث.","المال ليس المقصود في الحديث."]},
  {"q":"أي مما يأتي من صور الإحسان إلى الجار؟","o":["متابعة أسراره","زيارته إذا مرض","إزعاجه"],"a":1,"why":"زيارة الجار إذا مرض من صور الإحسان إليه، أما متابعة أسراره وإزعاجه فمن الإساءة التي نهى عنها الإسلام.","ow":["متابعة الأسرار إساءة.","","إزعاج الجار إساءة."]},
  {"q":"من الإساءة إلى الجار:","o":["ابتداؤه بالسلام","إيذاؤه بقول أو فعل","إهداؤه الطعام"],"a":1,"why":"إيذاء الجار بقول أو فعل إساءة إليه، أما ابتداؤه بالسلام وإهداؤه الطعام فمن الإحسان.","ow":["ابتداؤه بالسلام إحسان.","","إهداؤه الطعام إحسان."]},
  {"q":"قبّل النبي ﷺ حفيده:","o":["القاسم","عبدالله","الحسن بن علي"],"a":2,"why":"قبّل النبي ﷺ حفيده الحسن بن علي أمام الأقرع بن حابس، فقال له: «من لا يرحم لا يرحم».","ow":["القاسم ابنه ﷺ وليس حفيده.","عبد الله ابنه ﷺ وليس حفيده.",""]},
  {"q":"حمل النبي ﷺ في الصلاة حفيدته:","o":["فاطمة","أمامة بنت زينب","عائشة"],"a":1,"why":"حمل النبي ﷺ في الصلاة حفيدته أمامة بنت زينب، وهذا من رحمته بالأطفال. أما فاطمة فابنته وعائشة زوجته.","ow":["فاطمة ابنته وليست حفيدته.","","عائشة زوجته وليست حفيدته."]},
  {"q":"قال النبي ﷺ: «من لا يرحم ...»:","o":["يعاقب","يغفر له","لا يُرحم"],"a":2,"why":"قال النبي ﷺ: «من لا يرحم لا يرحم»، فمن لا يرحم غيره من الناس والحيوان لا يرحمه الله، وهذا يحثنا على الرحمة.","ow":["لا يعاقب بل لا يُرحم هو لفظ الحديث.","لا يغفر له، فالحديث «لا يُرحم».",""]},
  {"q":"سبب دخول امرأة النار في الحديث:","o":["كثرة صدقاتها","هرة حبستها","سفرها"],"a":1,"why":"دخلت امرأة النار بسبب هرة حبستها فلم تطعمها ولم تتركها. وليس بسبب الصدقة أو السفر.","ow":["كثرة الصدقات ليست سبب دخولها النار.","","السفر ليس سبب دخولها."]},
  {"q":"قال النبي ﷺ عن الحمّرة: «من فجع هذه بولدها؟ ...»:","o":["اتركوها","ردوا ولدها إليها","اذبحوها"],"a":1,"why":"قال النبي ﷺ عن الحمّرة: «من فجع هذه بولدها؟ ردوا ولدها إليها»، فأمر برد فرخيها رحمة منه بالطير.","ow":["لم يقل: اتركوها، بل أمر بإعادة فرخيها.","","لم يقل: اذبحوها."]},
  {"q":"قال النبي ﷺ: «من غشّ فليس ...»:","o":["منا جميعًا","بمسلم فقط","مني"],"a":2,"why":"قال النبي ﷺ: «من غش فليس مني»، فمن غشّ لم يكن على نهجه وطريقته، وهذا تحذير شديد من الغش في البيع وغيره.","ow":["«ليس منا جميعًا» ليس لفظ الحديث.","«ليس بمسلم فقط» ليس لفظ الحديث.",""]},
  {"q":"أخفى البائع الطعام المبلول:","o":["أسفل الكومة","أعلى الكومة","في البيت"],"a":0,"why":"أخفى البائع الطعام المبلول أسفل الكومة ووضع الجيد أعلاها ليخدع المشتري، فقال النبي ﷺ: «من غش فليس مني».","ow":["","لم يضعه أعلى الكومة.","لم يخبئه في بيته."]},
  {"q":"من أنواع الغش:","o":["الصدق في البيع","الغش في الاختبارات","إتقان العمل"],"a":1,"why":"من أنواع الغش الغش في الاختبارات، أما الصدق في البيع وإتقان العمل فمن الأخلاق الحسنة.","ow":["الصدق في البيع ليس غشًا.","","إتقان العمل ليس غشًا."]},
  {"q":"العبارة: كان النبي ﷺ يوصي بالإحسان إلى الجار.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: أوصى النبي ﷺ بالإحسان إلى الجار، فقال: «ما زال جبريل يوصيني بالجار».","ow":["","العبارة صحيحة، فقد أوصى بالجار كثيرًا."]},
  {"q":"العبارة: نهى النبي ﷺ عن اتخاذ الحيوان هدفًا لتعلم الرماية.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: نهى النبي ﷺ عن اتخاذ الحيوان هدفًا لتعلم الرماية، لأن ذلك من تعذيب الحيوان.","ow":["","العبارة صحيحة، فقد نهى عن ذلك رحمة بالحيوان."]},
  {"q":"العبارة: الغاش على نهج النبي ﷺ.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: الغاش ليس على نهج النبي ﷺ، فقد قال: «من غش فليس مني»، فلا يجوز الغش في البيع ولا في الاختبارات.","ow":["الصحيح أن الغاش ليس على نهجه، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: يشمل الإتقان الأمانة والمسؤولية تجاه الوطن.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: الإتقان من الأمانة والمسؤولية تجاه الوطن، فمن أتقن عمله خدم وطنه.","ow":["","العبارة صحيحة، فالإتقان أمانة."]}
];
window.BANK['so7']['so7-4-7'] = [
  {"q":"فُرض الحج في العام:","o":["5 هـ","9 هـ","10 هـ","1 هـ"],"a":1,"why":"فُرض الحج في العام 9 هـ بعد فتح مكة، أما العام 10 هـ فهو عام حج النبي ﷺ، أي حجة الوداع، فلا تخلط بينهما.","ow":["5 هـ عام الخندق.","","10 هـ عام حجة الوداع.","1 هـ عام الهجرة."]},
  {"q":"حج النبي ﷺ حجة واحدة سُميت:","o":["حجة الوداع","حجة الفتح","حجة البدر"],"a":0,"why":"حج النبي ﷺ حجة واحدة بعد الهجرة سُميت حجة الوداع، وذلك في العام العاشر الهجري، ولم يحج بعدها لأنه توفي.","ow":["","حجة الفتح ليس اسم حجته.","حجة البدر ليس اسمها."]},
  {"q":"بلغ عدد الحجاج في حجة الوداع أكثر من:","o":["10 آلاف","100 ألف","1000"],"a":1,"why":"بلغ عدد الحجاج في حجة الوداع أكثر من مئة ألف، فسارع المسلمون لما أعلن أنه يريد الحج.","ow":["10 آلاف أقل من العدد.","","1000 أقل بكثير من العدد."]},
  {"q":"قال النبي ﷺ: «لتأخذوا مناسككم فإني لا أدري لعلي لا ... بعد حجتي هذه»:","o":["أسافر","أحج","أصوم"],"a":1,"why":"قال النبي ﷺ: «لتأخذوا مناسككم فإني لا أدري لعلي لا أحج بعد حجتي هذه»، فكانت حجة الوداع.","ow":["لم يقل: لا أسافر.","","لم يقل: لا أصوم."]},
  {"q":"سُميت حجة البلاغ لأن النبي ﷺ:","o":["بلّغ الناس فيها","صام فيها","ودّع الناس فيها"],"a":0,"why":"سُميت حجة البلاغ لأن النبي ﷺ بلّغ الناس فيها الرسالة، أما الوداع فلأنه ودّع الناس.","ow":["","الصيام ليس سبب التسمية.","الوداع سبب تسمية حجة الوداع."]},
  {"q":"سُميت حجة الإسلام لأنه ﷺ:","o":["لم يترك شيئًا من قواعد الإسلام إلا بيّنه","غزا فيها","تزوج فيها"],"a":0,"why":"سُميت حجة الإسلام لأنه ﷺ لم يترك فيها شيئًا من قواعد الإسلام إلا بيّنه للناس، فكانت خطبته جامعة لأحكام الدين.","ow":["","لم تسمَّ بسبب الغزو.","لم تسمَّ بسبب الزواج."]},
  {"q":"جهّز النبي ﷺ جيشًا لنشر الإسلام في بلاد:","o":["اليمن","الشام","الحبشة"],"a":1,"why":"جهّز النبي ﷺ جيشًا لنشر الإسلام في بلاد الشام بقيادة أسامة بن زيد، وكان شابًا دون العشرين، ثم أنفذه أبو بكر.","ow":["اليمن لم تكن وجهة هذا الجيش.","","الحبشة لم تكن وجهة هذا الجيش."]},
  {"q":"كان أسامة بن زيد حين قيادة الجيش:","o":["دون العشرين من عمره","في الخمسين","في الأربعين"],"a":0,"why":"كان أسامة بن زيد حين قيادة الجيش دون العشرين من عمره، وهذا يدل على ثقة النبي ﷺ بالشباب.","ow":["","لم يكن في الخمسين.","لم يكن في الأربعين."]},
  {"q":"مرض النبي ﷺ بعد حجة الوداع بنحو:","o":["3 أشهر","سنة","يوم"],"a":0,"why":"مرض النبي ﷺ بعد حجة الوداع بنحو ثلاثة أشهر، ثم توفي بعد مرض دام عشرة أيام في بيت عائشة رضي الله عنها.","ow":["","سنة مدة أطول من الحقيقة.","يوم واحد مدة أقصر من الحقيقة."]},
  {"q":"مرض النبي ﷺ في بيت:","o":["خديجة","فاطمة","عائشة رضي الله عنها"],"a":2,"why":"مرض النبي ﷺ في بيت عائشة رضي الله عنها وبقي فيه حتى توفي، ودُفن فيه كذلك، فليس بيت خديجة ولا فاطمة.","ow":["بيت خديجة في مكة.","بيت فاطمة ليس المكان المذكور.",""]},
  {"q":"أمر النبي ﷺ في مرضه بإمامة الناس في الصلاة:","o":["أبا بكر الصديق","عمر","علي"],"a":0,"why":"أمر النبي ﷺ في مرضه أبا بكر الصديق بإمامة الناس في الصلاة، فكان إمامهم في أيام مرضه، وهذا يدل على مكانته.","ow":["","عمر لم يُذكر في هذا الأمر.","علي لم يُذكر في هذا الأمر."]},
  {"q":"مدة مرض النبي ﷺ:","o":["سنة","10 أيام","3 أيام"],"a":1,"why":"بلغت مدة مرض النبي ﷺ عشرة أيام، ثم توفي ﷺ في 12 ربيع الأول سنة 11 هـ، أي بعد نحو ثلاثة أشهر من حجة الوداع.","ow":["سنة أطول بكثير من المدة.","","3 أيام أقصر من المدة."]},
  {"q":"توفي النبي ﷺ يوم:","o":["الاثنين","الأحد","الجمعة"],"a":0,"why":"توفي النبي ﷺ ضحى يوم الاثنين من 12 ربيع الأول سنة 11 هـ، وكان ذلك آخر عهده بالدنيا بعد دعوة دامت 23 عامًا.","ow":["","الأحد ليس يوم وفاته.","الجمعة ليست يوم وفاته."]},
  {"q":"تاريخ وفاة النبي ﷺ:","o":["12 ربيع الأول","9 ذي الحجة","1 محرم"],"a":0,"why":"تاريخ وفاة النبي ﷺ 12 ربيع الأول، وهو اليوم نفسه الذي يوافق ميلاده في ربيع الأول.","ow":["","9 ذي الحجة يوم عرفة.","1 محرم بداية السنة الهجرية."]},
  {"q":"ترك النبي ﷺ أمرين:","o":["السيف والدرع","كتاب الله وسنة رسوله","المال والأرض"],"a":1,"why":"ترك النبي ﷺ أمرين من تمسك بهما لم يضل: كتاب الله وسنة رسوله، وليس سيفًا ولا مالًا.","ow":["السيف والدرع ليسا ما تركه ليتمسكوا به.","","المال والأرض ليسا ما تركه ليتمسكوا به."]},
  {"q":"تلا أبو بكر عند وفاة النبي ﷺ قوله تعالى: ﴿وما محمد إلا ...﴾:","o":["رسول","ملك","ساحر"],"a":0,"why":"تلا أبو بكر عند وفاة النبي ﷺ قوله تعالى: ﴿وما محمد إلا رسول﴾، ليذكر الناس أنه بشر رسول.","ow":["","الآية ليست ﴿وما محمد إلا ملك﴾.","الآية ليست ﴿وما محمد إلا ساحر﴾."]},
  {"q":"دُفن النبي ﷺ في:","o":["المسجد الحرام","بيت عائشة","البقيع"],"a":1,"why":"دُفن النبي ﷺ في بيت عائشة حيث توفي، وليس في المسجد الحرام ولا في البقيع، ثم دُخلت الحجرة في المسجد النبوي.","ow":["المسجد الحرام في مكة.","","البقيع مقبرة الصحابة بالمدينة."]},
  {"q":"غزوة الخندق كانت في السنة:","o":["2 هـ","10 هـ","5 هـ"],"a":2,"why":"وقعت غزوة الخندق في السنة الخامسة للهجرة، أما بدر فالثانية وأحد الثالثة وفتح مكة الثامنة، فاحفظ ترتيب الغزوات بالسنوات.","ow":["2 هـ هي سنة غزوة بدر وليست الخندق.","10 هـ سنة حجة الوداع.",""]},
  {"q":"فتح مكة كان في السنة:","o":["8 هـ","1 هـ","10 هـ"],"a":0,"why":"كان فتح مكة في السنة الثامنة للهجرة، أما 1 هـ فسنة الهجرة و10 هـ سنة حجة الوداع.","ow":["","1 هـ سنة الهجرة.","10 هـ سنة حجة الوداع."]},
  {"q":"العبارة: دعوة النبي ﷺ استمرت 23 عامًا.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: استمرت دعوة النبي ﷺ ثلاثة وعشرين عامًا، عانى فيها المتاعب وأقام فيها دولة قوية.","ow":["","العبارة صحيحة، فمدة الدعوة 23 عامًا."]},
  {"q":"العبارة: آخر ما نطق به النبي ﷺ الوصية بالصلاة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: كان آخر ما نطق به النبي ﷺ الوصية بالصلاة، تأكيدًا على أهميتها، فهي عماد الدين وأول ما يُحاسب عليه.","ow":["","العبارة صحيحة، فقد أوصى بالصلاة آخرًا."]},
  {"q":"العبارة: صلى المسلمون على النبي ﷺ جماعة جماعة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: صلى المسلمون على النبي ﷺ جماعة جماعة بعد أن غُسّل وكُفّن، ثم دُفن في بيت عائشة حيث توفي.","ow":["","العبارة صحيحة، فقد صلّوا عليه جماعات."]},
  {"q":"العبارة: حج النبي ﷺ بعد الهجرة ثلاث حجات.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: حج النبي ﷺ بعد الهجرة حجة واحدة هي حجة الوداع في العام العاشر، وليس ثلاث حجات كما في العبارة.","ow":["الصحيح أنه حج مرة واحدة، فالعبارة غير صحيحة.",""]}
];

